INSERT INTO "augments" VALUES('TFT17_Augment_EkkoGodAugment','17.1b','艾克的恩赐','获得【突变】，一个基于单位的定位为其提供强力进化的装备。获得2个【装备拆卸器】。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/GodAugmentEkko_II.TFT_Set17.tex','[]','{"NumRemovers_TOOLTIPONLY":2}','{"apiName":"TFT17_Augment_EkkoGodAugment","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f97\u3010\u7a81\u53d8\u3011\uff0c\u4e00\u4e2a\u57fa\u4e8e\u5355\u4f4d\u7684\u5b9a\u4f4d\u4e3a\u5176\u63d0\u4f9b\u5f3a\u529b\u8fdb\u5316\u7684\u88c5\u5907\u3002\u83b7\u5f972\u4e2a\u3010\u88c5\u5907\u62c6\u5378\u5668\u3011\u3002","effects":{"NumRemovers_TOOLTIPONLY":2},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/GodAugmentEkko_II.TFT_Set17.tex","id":null,"incompatibleTraits":[],"name":"\u827e\u514b\u7684\u6069\u8d50","tags":["{719abef1}"],"unique":false,"org":{"desc":"\u83b7\u5f97\u3010\u7a81\u53d8\u3011\uff0c\u4e00\u4e2a\u57fa\u4e8e\u5355\u4f4d\u7684\u5b9a\u4f4d\u4e3a\u5176\u63d0\u4f9b\u5f3a\u529b\u8fdb\u5316\u7684\u88c5\u5907\u3002\u83b7\u5f97@NumRemovers_TOOLTIPONLY@\u4e2a\u3010\u88c5\u5907\u62c6\u5378\u5668\u3011\u3002","effects":{"NumRemovers_TOOLTIPONLY":2}},"_key":"TFT17_Augment_EkkoGodAugment","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/GodAugmentEkko_II.TFT_Set17.png","removeSpaceName":"\u827e\u514b\u7684\u6069\u8d50"}');
INSERT INTO "augments" VALUES('TFT17_Augment_SorakaGodAugment','17.1b','索拉卡的恩赐','你每损失1玩家生命值，你的队伍就会获得2生命值。在每场玩家对战开始时，回复额外的1玩家生命值。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/GodAugmentSoraka_II.TFT_Set17.tex','[]','{"Heal":1,"HealthPerTacHealth":2}','{"apiName":"TFT17_Augment_SorakaGodAugment","associatedTraits":[],"composition":[],"desc":"\u4f60\u6bcf\u635f\u59311\u73a9\u5bb6\u751f\u547d\u503c\uff0c\u4f60\u7684\u961f\u4f0d\u5c31\u4f1a\u83b7\u5f972\u751f\u547d\u503c\u3002\u5728\u6bcf\u573a\u73a9\u5bb6\u5bf9\u6218\u5f00\u59cb\u65f6\uff0c\u56de\u590d\u989d\u5916\u76841\u73a9\u5bb6\u751f\u547d\u503c\u3002","effects":{"Heal":1,"HealthPerTacHealth":2},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/GodAugmentSoraka_II.TFT_Set17.tex","id":null,"incompatibleTraits":[],"name":"\u7d22\u62c9\u5361\u7684\u6069\u8d50","tags":["{719abef1}"],"unique":false,"org":{"desc":"\u4f60\u6bcf\u635f\u59311\u73a9\u5bb6\u751f\u547d\u503c\uff0c\u4f60\u7684\u961f\u4f0d\u5c31\u4f1a\u83b7\u5f97@HealthPerTacHealth@\u751f\u547d\u503c\u3002\u5728\u6bcf\u573a\u73a9\u5bb6\u5bf9\u6218\u5f00\u59cb\u65f6\uff0c\u56de\u590d\u989d\u5916\u7684@Heal@\u73a9\u5bb6\u751f\u547d\u503c\u3002","effects":{"Heal":1,"HealthPerTacHealth":2}},"_key":"TFT17_Augment_SorakaGodAugment","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/GodAugmentSoraka_II.TFT_Set17.png","removeSpaceName":"\u7d22\u62c9\u5361\u7684\u6069\u8d50"}');
INSERT INTO "augments" VALUES('TFT17_Augment_AnimaSquad_Commander','17.1b','幻灵指挥官','获得1个【贝蕾亚】、1个【金克丝】和1个【俄洛伊】。使你的当前和最大玩家生命值都提升10。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/AnimaCommander_II.TFT_Set17.tex','["TFT17_AnimaSquad"]','{"PlayerHealth":10}','{"apiName":"TFT17_Augment_AnimaSquad_Commander","associatedTraits":["TFT17_AnimaSquad"],"composition":[],"desc":"\u83b7\u5f971\u4e2a\u3010\u8d1d\u857e\u4e9a\u3011\u30011\u4e2a\u3010\u91d1\u514b\u4e1d\u3011\u548c1\u4e2a\u3010\u4fc4\u6d1b\u4f0a\u3011\u3002\u4f7f\u4f60\u7684\u5f53\u524d\u548c\u6700\u5927\u73a9\u5bb6\u751f\u547d\u503c\u90fd\u63d0\u534710\u3002","effects":{"PlayerHealth":10},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/AnimaCommander_II.TFT_Set17.tex","id":null,"incompatibleTraits":[],"name":"\u5e7b\u7075\u6307\u6325\u5b98","tags":["{ce1fd21c}","{b72bd3bf}","{3754d0ae}","{d22ae649}","{d12ae4b6}","{4529fead}","{84a6d904}","{77b330ea}"],"unique":false,"org":{"desc":"\u83b7\u5f971\u4e2a\u3010\u8d1d\u857e\u4e9a\u3011\u30011\u4e2a\u3010\u91d1\u514b\u4e1d\u3011\u548c1\u4e2a\u3010\u4fc4\u6d1b\u4f0a\u3011\u3002\u4f7f\u4f60\u7684\u5f53\u524d\u548c\u6700\u5927\u73a9\u5bb6\u751f\u547d\u503c\u90fd\u63d0\u5347@PlayerHealth@\u3002","effects":{"PlayerHealth":10}},"_key":"TFT17_Augment_AnimaSquad_Commander","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/AnimaCommander_II.TFT_Set17.png","removeSpaceName":"\u5e7b\u7075\u6307\u6325\u5b98"}');
