INSERT INTO "augments" VALUES('TFT17_Augment_InvaderZed','17.1b','天煞灭影：劫','获得1个【朔极之矛】。在回合4-2时，获得1个【劫】。在获得【劫】后，他才会在你的商店中出现。<br><br>【劫】是一名5费物理战士，可以创造出他自己的分身。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/InvaderZed_II.TFT_Set17.tex','[]','{"RoundNum":2,"StageNum":4}','{"apiName":"TFT17_Augment_InvaderZed","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f971\u4e2a\u3010\u6714\u6781\u4e4b\u77db\u3011\u3002\u5728\u56de\u54084-2\u65f6\uff0c\u83b7\u5f971\u4e2a\u3010\u52ab\u3011\u3002\u5728\u83b7\u5f97\u3010\u52ab\u3011\u540e\uff0c\u4ed6\u624d\u4f1a\u5728\u4f60\u7684\u5546\u5e97\u4e2d\u51fa\u73b0\u3002<br><br>\u3010\u52ab\u3011\u662f\u4e00\u540d5\u8d39\u7269\u7406\u6218\u58eb\uff0c\u53ef\u4ee5\u521b\u9020\u51fa\u4ed6\u81ea\u5df1\u7684\u5206\u8eab\u3002","effects":{"RoundNum":2,"StageNum":4},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/InvaderZed_II.TFT_Set17.tex","id":null,"incompatibleTraits":[],"name":"\u5929\u715e\u706d\u5f71\uff1a\u52ab","tags":["{ce1fd21c}","{b72bd3bf}","{d02ae323}","{d22ae649}","{ec068228}","{84a6d904}"],"unique":false,"org":{"desc":"\u83b7\u5f971\u4e2a\u3010\u6714\u6781\u4e4b\u77db\u3011\u3002\u5728\u56de\u5408@StageNum@-@RoundNum@\u65f6\uff0c\u83b7\u5f971\u4e2a\u3010\u52ab\u3011\u3002\u5728\u83b7\u5f97\u3010\u52ab\u3011\u540e\uff0c\u4ed6\u624d\u4f1a\u5728\u4f60\u7684\u5546\u5e97\u4e2d\u51fa\u73b0\u3002<br><br>\u3010\u52ab\u3011\u662f\u4e00\u540d5\u8d39\u7269\u7406\u6218\u58eb\uff0c\u53ef\u4ee5\u521b\u9020\u51fa\u4ed6\u81ea\u5df1\u7684\u5206\u8eab\u3002","effects":{"RoundNum":2,"StageNum":4}},"_key":"TFT17_Augment_InvaderZed","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/InvaderZed_II.TFT_Set17.png","removeSpaceName":"\u5929\u715e\u706d\u5f71\uff1a\u52ab"}');
