INSERT INTO "augments" VALUES('TFT17_Augment_EvelynnGodAugment','17.1b','伊芙琳的恩赐','你的队伍获得10%伤害减免。在你输掉对战回合时，额外失去1小小英雄生命值。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/GodAugmentEvelynn_II.TFT_Set17.tex','[]','{"Durability":0.10000000149011612,"HP":1}','{"apiName":"TFT17_Augment_EvelynnGodAugment","associatedTraits":[],"composition":[],"desc":"\u4f60\u7684\u961f\u4f0d\u83b7\u5f9710%\u4f24\u5bb3\u51cf\u514d\u3002\u5728\u4f60\u8f93\u6389\u5bf9\u6218\u56de\u5408\u65f6\uff0c\u989d\u5916\u5931\u53bb1\u5c0f\u5c0f\u82f1\u96c4\u751f\u547d\u503c\u3002","effects":{"Durability":0.10000000149011612,"HP":1},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/GodAugmentEvelynn_II.TFT_Set17.tex","id":null,"incompatibleTraits":[],"name":"\u4f0a\u8299\u7433\u7684\u6069\u8d50","tags":["{719abef1}"],"unique":false,"org":{"desc":"\u4f60\u7684\u961f\u4f0d\u83b7\u5f97@Durability*100@%\u4f24\u5bb3\u51cf\u514d\u3002\u5728\u4f60\u8f93\u6389\u5bf9\u6218\u56de\u5408\u65f6\uff0c\u989d\u5916\u5931\u53bb@HP@\u5c0f\u5c0f\u82f1\u96c4\u751f\u547d\u503c\u3002","effects":{"Durability":0.10000000149011612,"HP":1}},"_key":"TFT17_Augment_EvelynnGodAugment","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/GodAugmentEvelynn_II.TFT_Set17.png","removeSpaceName":"\u4f0a\u8299\u7433\u7684\u6069\u8d50"}');
