INSERT INTO "augments" VALUES('TFT9_Augment_ArmyBuilding','17.1b','团队建设','获得1个【次级英雄复制器】。在5个玩家对战回合后获得另一个。<br><br><rules>这个物品允许你能复制一个3费或以下的弈子。</rules>','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Building-an-army-I.tex','[]','{"PlayerCombatNum":5}','{"apiName":"TFT9_Augment_ArmyBuilding","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f971\u4e2a\u3010\u6b21\u7ea7\u82f1\u96c4\u590d\u5236\u5668\u3011\u3002\u57285\u4e2a\u73a9\u5bb6\u5bf9\u6218\u56de\u5408\u540e\u83b7\u5f97\u53e6\u4e00\u4e2a\u3002<br><br><rules>\u8fd9\u4e2a\u7269\u54c1\u5141\u8bb8\u4f60\u80fd\u590d\u5236\u4e00\u4e2a3\u8d39\u6216\u4ee5\u4e0b\u7684\u5f08\u5b50\u3002</rules>","effects":{"PlayerCombatNum":5},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Building-an-army-I.tex","id":null,"incompatibleTraits":[],"name":"\u56e2\u961f\u5efa\u8bbe","tags":["{d11fd6d5}","{b72bd3bf}","{d22ae649}","{7aaa3b47}","{94b91e70}"],"unique":false,"org":{"desc":"\u83b7\u5f971\u4e2a\u3010\u6b21\u7ea7\u82f1\u96c4\u590d\u5236\u5668\u3011\u3002\u5728@PlayerCombatNum@\u4e2a\u73a9\u5bb6\u5bf9\u6218\u56de\u5408\u540e\u83b7\u5f97\u53e6\u4e00\u4e2a\u3002<br><br><rules>\u8fd9\u4e2a\u7269\u54c1\u5141\u8bb8\u4f60\u80fd\u590d\u5236\u4e00\u4e2a3\u8d39\u6216\u4ee5\u4e0b\u7684\u5f08\u5b50\u3002</rules>","effects":{"PlayerCombatNum":5}},"_key":"TFT9_Augment_ArmyBuilding","tier":"silver","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Building-an-army-I.png","removeSpaceName":"\u56e2\u961f\u5efa\u8bbe"}');
