INSERT INTO "augments" VALUES('TFT6_Augment_HyperRoll','17.1b','花到上头','你不再获得利息，但会在每个玩家对战回合开始时获得3金币。立刻获得3金币。<br><br><rules>利息是你每储存10金币时获得的额外金币。</rules>','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Hyperroll2.tex','[]','{"Gold":3,"InitialGold":3,"XP":null}','{"apiName":"TFT6_Augment_HyperRoll","associatedTraits":[],"composition":[],"desc":"\u4f60\u4e0d\u518d\u83b7\u5f97\u5229\u606f\uff0c\u4f46\u4f1a\u5728\u6bcf\u4e2a\u73a9\u5bb6\u5bf9\u6218\u56de\u5408\u5f00\u59cb\u65f6\u83b7\u5f973\u91d1\u5e01\u3002\u7acb\u523b\u83b7\u5f973\u91d1\u5e01\u3002<br><br><rules>\u5229\u606f\u662f\u4f60\u6bcf\u50a8\u5b5810\u91d1\u5e01\u65f6\u83b7\u5f97\u7684\u989d\u5916\u91d1\u5e01\u3002</rules>","effects":{"Gold":3,"InitialGold":3,"XP":null},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Hyperroll2.tex","id":null,"incompatibleTraits":[],"name":"\u82b1\u5230\u4e0a\u5934","tags":["{ce1fd21c}","{b72bd3bf}","{92e7310e}","{24d36c27}","{d22ae649}","{d12ae4b6}","{af5e87d2}","{4529fead}"],"unique":false,"org":{"desc":"\u4f60\u4e0d\u518d\u83b7\u5f97\u5229\u606f\uff0c\u4f46\u4f1a\u5728\u6bcf\u4e2a\u73a9\u5bb6\u5bf9\u6218\u56de\u5408\u5f00\u59cb\u65f6\u83b7\u5f97@Gold@\u91d1\u5e01\u3002\u7acb\u523b\u83b7\u5f97@InitialGold@\u91d1\u5e01\u3002<br><br><rules>\u5229\u606f\u662f\u4f60\u6bcf\u50a8\u5b5810\u91d1\u5e01\u65f6\u83b7\u5f97\u7684\u989d\u5916\u91d1\u5e01\u3002</rules>","effects":{"Gold":3,"InitialGold":3,"XP":null}},"_key":"TFT6_Augment_HyperRoll","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Hyperroll2.png","removeSpaceName":"\u82b1\u5230\u4e0a\u5934"}');
