INSERT INTO "augments" VALUES('TFT_Augment_Replication','17.1b','反响','在3件基础装备中选择1件。在接下来的2回合，获得1件该基础装备。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Replication-II.tex','[]','{"Gold":null,"roundsofbonusitems":2}','{"apiName":"TFT_Augment_Replication","associatedTraits":[],"composition":[],"desc":"\u57283\u4ef6\u57fa\u7840\u88c5\u5907\u4e2d\u9009\u62e91\u4ef6\u3002\u5728\u63a5\u4e0b\u6765\u76842\u56de\u5408\uff0c\u83b7\u5f971\u4ef6\u8be5\u57fa\u7840\u88c5\u5907\u3002","effects":{"Gold":null,"roundsofbonusitems":2},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Replication-II.tex","id":null,"incompatibleTraits":[],"name":"\u53cd\u54cd","tags":["{ce1fd21c}","{b72bd3bf}","{d22ae649}","{8fba48a3}"],"unique":false,"org":{"desc":"\u57283\u4ef6\u57fa\u7840\u88c5\u5907\u4e2d\u9009\u62e91\u4ef6\u3002\u5728\u63a5\u4e0b\u6765\u7684@RoundsOfBonusItems@\u56de\u5408\uff0c\u83b7\u5f971\u4ef6\u8be5\u57fa\u7840\u88c5\u5907\u3002","effects":{"Gold":null,"roundsofbonusitems":2}},"_key":"TFT_Augment_Replication","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Replication-II.png","removeSpaceName":"\u53cd\u54cd"}');
INSERT INTO "augments" VALUES('TFT10_Augment_CrashTestDummies','17.1b','碰撞测试假人','获得2个【训练假人】。战斗开始时：你的【目标假人】们会将自己发射向敌人最密集的位置并将其晕眩1秒。 ','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Crash-Test-Dummies-II.tex','[]','{"NumDummies":2,"SearchRange":4,"Stun":1}','{"apiName":"TFT10_Augment_CrashTestDummies","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f972\u4e2a\u3010\u8bad\u7ec3\u5047\u4eba\u3011\u3002\u6218\u6597\u5f00\u59cb\u65f6\uff1a\u4f60\u7684\u3010\u76ee\u6807\u5047\u4eba\u3011\u4eec\u4f1a\u5c06\u81ea\u5df1\u53d1\u5c04\u5411\u654c\u4eba\u6700\u5bc6\u96c6\u7684\u4f4d\u7f6e\u5e76\u5c06\u5176\u6655\u77291\u79d2\u3002 ","effects":{"NumDummies":2,"SearchRange":4,"Stun":1},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Crash-Test-Dummies-II.tex","id":null,"incompatibleTraits":[],"name":"\u78b0\u649e\u6d4b\u8bd5\u5047\u4eba","tags":["{b72bd3bf}","{d02ae323}","{807eed8a}","{ce1fd21c}"],"unique":false,"org":{"desc":"\u83b7\u5f97@Numdummies@\u4e2a\u3010\u8bad\u7ec3\u5047\u4eba\u3011\u3002\u6218\u6597\u5f00\u59cb\u65f6\uff1a\u4f60\u7684\u3010\u76ee\u6807\u5047\u4eba\u3011\u4eec\u4f1a\u5c06\u81ea\u5df1\u53d1\u5c04\u5411\u654c\u4eba\u6700\u5bc6\u96c6\u7684\u4f4d\u7f6e\u5e76\u5c06\u5176\u6655\u7729@stun@\u79d2\u3002 ","effects":{"NumDummies":2,"SearchRange":4,"Stun":1}},"_key":"TFT10_Augment_CrashTestDummies","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Crash-Test-Dummies-II.png","removeSpaceName":"\u78b0\u649e\u6d4b\u8bd5\u5047\u4eba"}');
INSERT INTO "augments" VALUES('TFT7_Augment_LuckyGlovesPlus','17.1b','幸运手套+','【窃贼手套】总会为你的弈子们提供推荐装备。即刻获得2个【拳套】，然后在4场玩家对战后获得另一个。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Lucky-Gloves-III.tex','[]','{"DelayTurns":4,"NumGloves":2}','{"apiName":"TFT7_Augment_LuckyGlovesPlus","associatedTraits":[],"composition":[],"desc":"\u3010\u7a83\u8d3c\u624b\u5957\u3011\u603b\u4f1a\u4e3a\u4f60\u7684\u5f08\u5b50\u4eec\u63d0\u4f9b\u63a8\u8350\u88c5\u5907\u3002\u5373\u523b\u83b7\u5f972\u4e2a\u3010\u62f3\u5957\u3011\uff0c\u7136\u540e\u57284\u573a\u73a9\u5bb6\u5bf9\u6218\u540e\u83b7\u5f97\u53e6\u4e00\u4e2a\u3002","effects":{"DelayTurns":4,"NumGloves":2},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Lucky-Gloves-III.tex","id":null,"incompatibleTraits":[],"name":"\u5e78\u8fd0\u624b\u5957+","tags":["{cf1fd3af}","{b72bd3bf}","{d02ae323}","{8fba48a3}"],"unique":false,"org":{"desc":"\u3010\u7a83\u8d3c\u624b\u5957\u3011\u603b\u4f1a\u4e3a\u4f60\u7684\u5f08\u5b50\u4eec\u63d0\u4f9b\u63a8\u8350\u88c5\u5907\u3002\u5373\u523b\u83b7\u5f97@NumGloves@\u4e2a\u3010\u62f3\u5957\u3011\uff0c\u7136\u540e\u5728@DelayTurns@\u573a\u73a9\u5bb6\u5bf9\u6218\u540e\u83b7\u5f97\u53e6\u4e00\u4e2a\u3002","effects":{"DelayTurns":4,"NumGloves":2}},"_key":"TFT7_Augment_LuckyGlovesPlus","tier":"prism","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Lucky-Gloves-III.png","removeSpaceName":"\u5e78\u8fd0\u624b\u5957+"}');
INSERT INTO "augments" VALUES('TFT_Augment_Dummify','17.1b','假人化','失去你场上和备战席上的所有弈子。获得1个【训练假人】，其生命值为失去所有弈子总生命值的60%。这个【训练假人】每阶段获得1000生命值。获得1个非坦克的2星2费弈子。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Dummify_I.TFT_Set13.tex','[]','{"ChampCost":2,"HPPerStage":1000,"HealthPercent":60}','{"apiName":"TFT_Augment_Dummify","associatedTraits":[],"composition":[],"desc":"\u5931\u53bb\u4f60\u573a\u4e0a\u548c\u5907\u6218\u5e2d\u4e0a\u7684\u6240\u6709\u5f08\u5b50\u3002\u83b7\u5f971\u4e2a\u3010\u8bad\u7ec3\u5047\u4eba\u3011\uff0c\u5176\u751f\u547d\u503c\u4e3a\u5931\u53bb\u6240\u6709\u5f08\u5b50\u603b\u751f\u547d\u503c\u768460%\u3002\u8fd9\u4e2a\u3010\u8bad\u7ec3\u5047\u4eba\u3011\u6bcf\u9636\u6bb5\u83b7\u5f971000\u751f\u547d\u503c\u3002\u83b7\u5f971\u4e2a\u975e\u5766\u514b\u76842\u661f2\u8d39\u5f08\u5b50\u3002","effects":{"ChampCost":2,"HPPerStage":1000,"HealthPercent":60},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Dummify_I.TFT_Set13.tex","id":null,"incompatibleTraits":[],"name":"\u5047\u4eba\u5316","tags":["{d11fd6d5}","{b72bd3bf}","{92e7310e}","{d02ae323}","{d22ae649}","{c5c463aa}","{807eed8a}"],"unique":false,"org":{"desc":"\u5931\u53bb\u4f60\u573a\u4e0a\u548c\u5907\u6218\u5e2d\u4e0a\u7684\u6240\u6709\u5f08\u5b50\u3002\u83b7\u5f971\u4e2a\u3010\u8bad\u7ec3\u5047\u4eba\u3011\uff0c\u5176\u751f\u547d\u503c\u4e3a\u5931\u53bb\u6240\u6709\u5f08\u5b50\u603b\u751f\u547d\u503c\u7684@HealthPercent@%\u3002\u8fd9\u4e2a\u3010\u8bad\u7ec3\u5047\u4eba\u3011\u6bcf\u9636\u6bb5\u83b7\u5f97@HPPerStage@\u751f\u547d\u503c\u3002\u83b7\u5f971\u4e2a\u975e\u5766\u514b\u76842\u661f@ChampCost@\u8d39\u5f08\u5b50\u3002","effects":{"ChampCost":2,"HPPerStage":1000,"HealthPercent":60}},"_key":"TFT_Augment_Dummify","tier":"silver","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Dummify_I.TFT_Set13.png","removeSpaceName":"\u5047\u4eba\u5316"}');
INSERT INTO "augments" VALUES('TFT_Augment_PatienceIsAVirtue','17.1b','耐心是一种美德','立刻获得@InitialRerolls@次刷新。每回合，如果你在上一回合未购买任何弈子，则会获得1次免费刷新。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/PatienceIsAVirtue_I.TFT_Set12.tex','[]','{"FreeRerolls":1,"{4293de94}":null,"{a4a3332a}":4}','{"apiName":"TFT_Augment_PatienceIsAVirtue","associatedTraits":[],"composition":[],"desc":"\u7acb\u523b\u83b7\u5f97@InitialRerolls@\u6b21\u5237\u65b0\u3002\u6bcf\u56de\u5408\uff0c\u5982\u679c\u4f60\u5728\u4e0a\u4e00\u56de\u5408\u672a\u8d2d\u4e70\u4efb\u4f55\u5f08\u5b50\uff0c\u5219\u4f1a\u83b7\u5f971\u6b21\u514d\u8d39\u5237\u65b0\u3002","effects":{"FreeRerolls":1,"{4293de94}":null,"{a4a3332a}":4},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/PatienceIsAVirtue_I.TFT_Set12.tex","id":null,"incompatibleTraits":[],"name":"\u8010\u5fc3\u662f\u4e00\u79cd\u7f8e\u5fb7","tags":["{d11fd6d5}","{b72bd3bf}","{24d36c27}","{d22ae649}","{d12ae4b6}","{7aaa3b47}"],"unique":false,"org":{"desc":"\u7acb\u523b\u83b7\u5f97@InitialRerolls@\u6b21\u5237\u65b0\u3002\u6bcf\u56de\u5408\uff0c\u5982\u679c\u4f60\u5728\u4e0a\u4e00\u56de\u5408\u672a\u8d2d\u4e70\u4efb\u4f55\u5f08\u5b50\uff0c\u5219\u4f1a\u83b7\u5f97@FreeRerolls@\u6b21\u514d\u8d39\u5237\u65b0\u3002","effects":{"FreeRerolls":1,"{4293de94}":null,"{a4a3332a}":4}},"_key":"TFT_Augment_PatienceIsAVirtue","tier":"silver","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/PatienceIsAVirtue_I.TFT_Set12.png","balance":0,"diff":{"effects":["FreeRerolls","{a4a3332a}"]},"removeSpaceName":"\u8010\u5fc3\u662f\u4e00\u79cd\u7f8e\u5fb7"}');
