INSERT INTO "augments" VALUES('TFT_Augment_HeavyIsTheCrown','17.1b','王冠之重','获得一个【德玛西亚王冠】，它会对携带者提供各种显著加成。如果携带者阵亡，就会输掉该回合。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/HeavyIsTheCrown_II.TFT_Set15.tex','[]','{}','{"apiName":"TFT_Augment_HeavyIsTheCrown","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f97\u4e00\u4e2a\u3010\u5fb7\u739b\u897f\u4e9a\u738b\u51a0\u3011\uff0c\u5b83\u4f1a\u5bf9\u643a\u5e26\u8005\u63d0\u4f9b\u5404\u79cd\u663e\u8457\u52a0\u6210\u3002\u5982\u679c\u643a\u5e26\u8005\u9635\u4ea1\uff0c\u5c31\u4f1a\u8f93\u6389\u8be5\u56de\u5408\u3002","effects":{},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/HeavyIsTheCrown_II.TFT_Set15.tex","id":null,"incompatibleTraits":[],"name":"\u738b\u51a0\u4e4b\u91cd","tags":["{ce1fd21c}","{b72bd3bf}","{d22ae649}","{8fba48a3}","{92e7310e}","{77b330ea}"],"unique":false,"org":{"desc":"\u83b7\u5f97\u4e00\u4e2a\u3010\u5fb7\u739b\u897f\u4e9a\u738b\u51a0\u3011\uff0c\u5b83\u4f1a\u5bf9\u643a\u5e26\u8005\u63d0\u4f9b\u5404\u79cd\u663e\u8457\u52a0\u6210\u3002\u5982\u679c\u643a\u5e26\u8005\u9635\u4ea1\uff0c\u5c31\u4f1a\u8f93\u6389\u8be5\u56de\u5408\u3002","effects":{}},"_key":"TFT_Augment_HeavyIsTheCrown","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/HeavyIsTheCrown_II.TFT_Set15.png","removeSpaceName":"\u738b\u51a0\u4e4b\u91cd"}');
INSERT INTO "augments" VALUES('TFT_Augment_HardCommit','17.1b','硬性承诺','获得1个随机纹章。现在以及每个阶段开始时，获得该羁绊的一个1星弈子，且该弈子的费用相当于当前阶段数(最多为5)，并获得4金币。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/HardCommit_III.TFT_Set12.tex','[]','{"GoldPerStage":4}','{"apiName":"TFT_Augment_HardCommit","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f971\u4e2a\u968f\u673a\u7eb9\u7ae0\u3002\u73b0\u5728\u4ee5\u53ca\u6bcf\u4e2a\u9636\u6bb5\u5f00\u59cb\u65f6\uff0c\u83b7\u5f97\u8be5\u7f81\u7eca\u7684\u4e00\u4e2a1\u661f\u5f08\u5b50\uff0c\u4e14\u8be5\u5f08\u5b50\u7684\u8d39\u7528\u76f8\u5f53\u4e8e\u5f53\u524d\u9636\u6bb5\u6570(\u6700\u591a\u4e3a5)\uff0c\u5e76\u83b7\u5f974\u91d1\u5e01\u3002","effects":{"GoldPerStage":4},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/HardCommit_III.TFT_Set12.tex","id":null,"incompatibleTraits":[],"name":"\u786c\u6027\u627f\u8bfa","tags":["{cf1fd3af}","{b72bd3bf}","{d22ae649}","{7aaa3b47}","{d12ae4b6}","{382a7131}","{38bcced7}"],"unique":false,"org":{"desc":"\u83b7\u5f971\u4e2a\u968f\u673a\u7eb9\u7ae0\u3002\u73b0\u5728\u4ee5\u53ca\u6bcf\u4e2a\u9636\u6bb5\u5f00\u59cb\u65f6\uff0c\u83b7\u5f97\u8be5\u7f81\u7eca\u7684\u4e00\u4e2a1\u661f\u5f08\u5b50\uff0c\u4e14\u8be5\u5f08\u5b50\u7684\u8d39\u7528\u76f8\u5f53\u4e8e\u5f53\u524d\u9636\u6bb5\u6570(\u6700\u591a\u4e3a5)\uff0c\u5e76\u83b7\u5f97@GoldPerStage@\u91d1\u5e01\u3002","effects":{"GoldPerStage":4}},"_key":"TFT_Augment_HardCommit","tier":"prism","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/HardCommit_III.TFT_Set12.png","removeSpaceName":"\u786c\u6027\u627f\u8bfa"}');
