INSERT INTO "augments" VALUES('TFT_Augment_TheVidalion','17.1b','纺织魔法','获得1件随机基础装备。你的小队每消耗2200法力值，就会提供1个额外基础装备(装备获得进度@TFTUnitProperty.trait:TFT_Augment_TheVidalion_NumComponents@/3)。<br><br><rules>已消耗的法力值：@TFTUnitProperty.trait:TFT_Augment_TheVidalion_TrackedMana@/2200</rules>','ASSETS/Maps/TFT/Icons/Augments/Hexcore/WovenMagic_III.TFT_Set16.tex','[]','{"ComponentMax":3,"ManaPerComponent":2200}','{"apiName":"TFT_Augment_TheVidalion","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f971\u4ef6\u968f\u673a\u57fa\u7840\u88c5\u5907\u3002\u4f60\u7684\u5c0f\u961f\u6bcf\u6d88\u80172200\u6cd5\u529b\u503c\uff0c\u5c31\u4f1a\u63d0\u4f9b1\u4e2a\u989d\u5916\u57fa\u7840\u88c5\u5907(\u88c5\u5907\u83b7\u5f97\u8fdb\u5ea6@TFTUnitProperty.trait:TFT_Augment_TheVidalion_NumComponents@/3)\u3002<br><br><rules>\u5df2\u6d88\u8017\u7684\u6cd5\u529b\u503c\uff1a@TFTUnitProperty.trait:TFT_Augment_TheVidalion_TrackedMana@/2200</rules>","effects":{"ComponentMax":3,"ManaPerComponent":2200},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/WovenMagic_III.TFT_Set16.tex","id":null,"incompatibleTraits":[],"name":"\u7eba\u7ec7\u9b54\u6cd5","tags":["{ce1fd21c}","{b72bd3bf}","{d22ae649}","{d12ae4b6}"],"unique":false,"org":{"desc":"\u83b7\u5f971\u4ef6\u968f\u673a\u57fa\u7840\u88c5\u5907\u3002\u4f60\u7684\u5c0f\u961f\u6bcf\u6d88\u8017@ManaPerComponent@\u6cd5\u529b\u503c\uff0c\u5c31\u4f1a\u63d0\u4f9b1\u4e2a\u989d\u5916\u57fa\u7840\u88c5\u5907(\u88c5\u5907\u83b7\u5f97\u8fdb\u5ea6@TFTUnitProperty.trait:TFT_Augment_TheVidalion_NumComponents@/@ComponentMax@)\u3002<br><br><rules>\u5df2\u6d88\u8017\u7684\u6cd5\u529b\u503c\uff1a@TFTUnitProperty.trait:TFT_Augment_TheVidalion_TrackedMana@/@ManaPerComponent@</rules>","effects":{"ComponentMax":3,"ManaPerComponent":2200}},"_key":"TFT_Augment_TheVidalion","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/WovenMagic_III.TFT_Set16.png","removeSpaceName":"\u7eba\u7ec7\u9b54\u6cd5"}');
INSERT INTO "augments" VALUES('TFT_Augment_Expedition','17.1b','远征','每个回合开始时，损失备战席最右侧栏位的弈子。当你通过这种方式损失的弈子总价值达到33金币时，获得强力奖励。立刻获得1个3费弈子。@TFTUnitProperty.item:TFT_Augment_Expedition_Tooltip@','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Expedition_I.TFT_Set17.tex','[]','{"CashoutCost":33,"{b763af5c}":1}','{"apiName":"TFT_Augment_Expedition","associatedTraits":[],"composition":[],"desc":"\u6bcf\u4e2a\u56de\u5408\u5f00\u59cb\u65f6\uff0c\u635f\u5931\u5907\u6218\u5e2d\u6700\u53f3\u4fa7\u680f\u4f4d\u7684\u5f08\u5b50\u3002\u5f53\u4f60\u901a\u8fc7\u8fd9\u79cd\u65b9\u5f0f\u635f\u5931\u7684\u5f08\u5b50\u603b\u4ef7\u503c\u8fbe\u523033\u91d1\u5e01\u65f6\uff0c\u83b7\u5f97\u5f3a\u529b\u5956\u52b1\u3002\u7acb\u523b\u83b7\u5f971\u4e2a3\u8d39\u5f08\u5b50\u3002@TFTUnitProperty.item:TFT_Augment_Expedition_Tooltip@","effects":{"CashoutCost":33,"{b763af5c}":1},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Expedition_I.TFT_Set17.tex","id":null,"incompatibleTraits":[],"name":"\u8fdc\u5f81","tags":["{d11fd6d5}","{d22ae649}","{d12ae4b6}","{b72bd3bf}","{7aaa3b47}","{77b330ea}","{4529fead}","{92e7310e}"],"unique":false,"org":{"desc":"\u6bcf\u4e2a\u56de\u5408\u5f00\u59cb\u65f6\uff0c\u635f\u5931\u5907\u6218\u5e2d\u6700\u53f3\u4fa7\u680f\u4f4d\u7684\u5f08\u5b50\u3002\u5f53\u4f60\u901a\u8fc7\u8fd9\u79cd\u65b9\u5f0f\u635f\u5931\u7684\u5f08\u5b50\u603b\u4ef7\u503c\u8fbe\u5230@CashoutCost@\u91d1\u5e01\u65f6\uff0c\u83b7\u5f97\u5f3a\u529b\u5956\u52b1\u3002\u7acb\u523b\u83b7\u5f971\u4e2a3\u8d39\u5f08\u5b50\u3002@TFTUnitProperty.item:TFT_Augment_Expedition_Tooltip@","effects":{"CashoutCost":33,"{b763af5c}":1}},"_key":"TFT_Augment_Expedition","tier":"silver","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Expedition_I.TFT_Set17.png","removeSpaceName":"\u8fdc\u5f81"}');
