INSERT INTO "augments" VALUES('TFT_Augment_ClimbTheLadder2','17.1b','攀登天梯 II','每当一名友军阵亡，至少与其共享一个羁绊的友军会获得5%法术加成、5%物理加成、5护甲和5魔法抗性。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/ClimbtheLadder_II.TFT_Set13.tex','[]','{"BonusAD":0.05000000074505806,"BonusAP":5,"BonusArmor":5,"BonusMR":5}','{"apiName":"TFT_Augment_ClimbTheLadder2","associatedTraits":[],"composition":[],"desc":"\u6bcf\u5f53\u4e00\u540d\u53cb\u519b\u9635\u4ea1\uff0c\u81f3\u5c11\u4e0e\u5176\u5171\u4eab\u4e00\u4e2a\u7f81\u7eca\u7684\u53cb\u519b\u4f1a\u83b7\u5f975%\u6cd5\u672f\u52a0\u6210\u30015%\u7269\u7406\u52a0\u6210\u30015\u62a4\u7532\u548c5\u9b54\u6cd5\u6297\u6027\u3002","effects":{"BonusAD":0.05000000074505806,"BonusAP":5,"BonusArmor":5,"BonusMR":5},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/ClimbtheLadder_II.TFT_Set13.tex","id":null,"incompatibleTraits":[],"name":"\u6500\u767b\u5929\u68af II","tags":["{ce1fd21c}","{b72bd3bf}","{d02ae323}","{ee609993}","{807eed8a}"],"unique":false,"org":{"desc":"\u6bcf\u5f53\u4e00\u540d\u53cb\u519b\u9635\u4ea1\uff0c\u81f3\u5c11\u4e0e\u5176\u5171\u4eab\u4e00\u4e2a\u7f81\u7eca\u7684\u53cb\u519b\u4f1a\u83b7\u5f97@BonusAP@%\u6cd5\u672f\u52a0\u6210\u3001@BonusAD*100@%\u7269\u7406\u52a0\u6210\u3001@BonusArmor@\u62a4\u7532\u548c@BonusMR@\u9b54\u6cd5\u6297\u6027\u3002","effects":{"BonusAD":0.05000000074505806,"BonusAP":5,"BonusArmor":5,"BonusMR":5}},"_key":"TFT_Augment_ClimbTheLadder2","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/ClimbtheLadder_II.TFT_Set13.png","removeSpaceName":"\u6500\u767b\u5929\u68afII"}');
