INSERT INTO "augments" VALUES('TFT_Augment_UrfsGambit','17.1b','海牛阿福的锅铲战术','如果你赢了你的下一个玩家对战回合，获得1个【金铲铲】。如果你输了，获得1个【金锅锅】。立刻获得1个【基础装备锻造器】和6金币。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/UrfsGambit_II.TFT_Set16.tex','[]','{"Gold":6}','{"apiName":"TFT_Augment_UrfsGambit","associatedTraits":[],"composition":[],"desc":"\u5982\u679c\u4f60\u8d62\u4e86\u4f60\u7684\u4e0b\u4e00\u4e2a\u73a9\u5bb6\u5bf9\u6218\u56de\u5408\uff0c\u83b7\u5f971\u4e2a\u3010\u91d1\u94f2\u94f2\u3011\u3002\u5982\u679c\u4f60\u8f93\u4e86\uff0c\u83b7\u5f971\u4e2a\u3010\u91d1\u9505\u9505\u3011\u3002\u7acb\u523b\u83b7\u5f971\u4e2a\u3010\u57fa\u7840\u88c5\u5907\u953b\u9020\u5668\u3011\u548c6\u91d1\u5e01\u3002","effects":{"Gold":6},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/UrfsGambit_II.TFT_Set16.tex","id":null,"incompatibleTraits":[],"name":"\u6d77\u725b\u963f\u798f\u7684\u9505\u94f2\u6218\u672f","tags":["{ce1fd21c}","{b72bd3bf}","{d02ae323}","{d22ae649}"],"unique":false,"org":{"desc":"\u5982\u679c\u4f60\u8d62\u4e86\u4f60\u7684\u4e0b\u4e00\u4e2a\u73a9\u5bb6\u5bf9\u6218\u56de\u5408\uff0c\u83b7\u5f971\u4e2a\u3010\u91d1\u94f2\u94f2\u3011\u3002\u5982\u679c\u4f60\u8f93\u4e86\uff0c\u83b7\u5f971\u4e2a\u3010\u91d1\u9505\u9505\u3011\u3002\u7acb\u523b\u83b7\u5f971\u4e2a\u3010\u57fa\u7840\u88c5\u5907\u953b\u9020\u5668\u3011\u548c@Gold@\u91d1\u5e01\u3002","effects":{"Gold":6}},"_key":"TFT_Augment_UrfsGambit","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/UrfsGambit_II.TFT_Set16.png","removeSpaceName":"\u6d77\u725b\u963f\u798f\u7684\u9505\u94f2\u6218\u672f"}');
