INSERT INTO "augments" VALUES('TFT_Augment_SoloLeveling','17.1b','独自升级','在接下来的5个战斗回合，你的小队规模为1，但你登场的那个弈子拥有巨幅提升过的各属性。该弈子的每次击杀都会使你获得1经验。在此之后，获得2件基础装备。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/SoloLeveling_II.TFT_Set15.tex','[]','{"ADBonus":0.5,"APBonus":50,"ASBonus":0.5,"DamageAmpBonus":0.30000001192092896,"DurabilityBonus":0.20000000298023224,"FlatHealthBonus":525,"NumCombats":5,"NumComponents":2,"OmnivampBonus":0.20000000298023224,"XPPerKill":1}','{"apiName":"TFT_Augment_SoloLeveling","associatedTraits":[],"composition":[],"desc":"\u5728\u63a5\u4e0b\u6765\u76845\u4e2a\u6218\u6597\u56de\u5408\uff0c\u4f60\u7684\u5c0f\u961f\u89c4\u6a21\u4e3a1\uff0c\u4f46\u4f60\u767b\u573a\u7684\u90a3\u4e2a\u5f08\u5b50\u62e5\u6709\u5de8\u5e45\u63d0\u5347\u8fc7\u7684\u5404\u5c5e\u6027\u3002\u8be5\u5f08\u5b50\u7684\u6bcf\u6b21\u51fb\u6740\u90fd\u4f1a\u4f7f\u4f60\u83b7\u5f971\u7ecf\u9a8c\u3002\u5728\u6b64\u4e4b\u540e\uff0c\u83b7\u5f972\u4ef6\u57fa\u7840\u88c5\u5907\u3002","effects":{"ADBonus":0.5,"APBonus":50,"ASBonus":0.5,"DamageAmpBonus":0.30000001192092896,"DurabilityBonus":0.20000000298023224,"FlatHealthBonus":525,"NumCombats":5,"NumComponents":2,"OmnivampBonus":0.20000000298023224,"XPPerKill":1},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/SoloLeveling_II.TFT_Set15.tex","id":null,"incompatibleTraits":[],"name":"\u72ec\u81ea\u5347\u7ea7","tags":["{ce1fd21c}","{b72bd3bf}","{92e7310e}","{d12ae4b6}","{d22ae649}","{4529fead}"],"unique":false,"org":{"desc":"\u5728\u63a5\u4e0b\u6765\u7684@NumCombats@\u4e2a\u6218\u6597\u56de\u5408\uff0c\u4f60\u7684\u5c0f\u961f\u89c4\u6a21\u4e3a1\uff0c\u4f46\u4f60\u767b\u573a\u7684\u90a3\u4e2a\u5f08\u5b50\u62e5\u6709\u5de8\u5e45\u63d0\u5347\u8fc7\u7684\u5404\u5c5e\u6027\u3002\u8be5\u5f08\u5b50\u7684\u6bcf\u6b21\u51fb\u6740\u90fd\u4f1a\u4f7f\u4f60\u83b7\u5f97@XPPerKill@\u7ecf\u9a8c\u3002\u5728\u6b64\u4e4b\u540e\uff0c\u83b7\u5f97@NumComponents@\u4ef6\u57fa\u7840\u88c5\u5907\u3002","effects":{"ADBonus":0.5,"APBonus":50,"ASBonus":0.5,"DamageAmpBonus":