INSERT INTO "augments" VALUES('TFT_Augment_TreasureHunt','17.1b','寻宝','在现在和第null阶段之间的每个阶段获得一个上锁的宝箱。当你在商店刷新上花费null金币时，即可解锁一个宝箱。这些宝箱会存留至被打开为止。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/TreasureHunt_II.TFT_Set15.tex','[]','{"GoldNeededPerChest":null,"MaxNumChests":null}','{"apiName":"TFT_Augment_TreasureHunt","associatedTraits":[],"composition":[],"desc":"\u5728\u73b0\u5728\u548c\u7b2cnull\u9636\u6bb5\u4e4b\u95f4\u7684\u6bcf\u4e2a\u9636\u6bb5\u83b7\u5f97\u4e00\u4e2a\u4e0a\u9501\u7684\u5b9d\u7bb1\u3002\u5f53\u4f60\u5728\u5546\u5e97\u5237\u65b0\u4e0a\u82b1\u8d39null\u91d1\u5e01\u65f6\uff0c\u5373\u53ef\u89e3\u9501\u4e00\u4e2a\u5b9d\u7bb1\u3002\u8fd9\u4e9b\u5b9d\u7bb1\u4f1a\u5b58\u7559\u81f3\u88ab\u6253\u5f00\u4e3a\u6b62\u3002","effects":{"GoldNeededPerChest":null,"MaxNumChests":null},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/TreasureHunt_II.TFT_Set15.tex","id":null,"incompatibleTraits":[],"name":"\u5bfb\u5b9d","tags":["{ce1fd21c}","{0d98debd}","{d12ae4b6}","{d22ae649}","{8fba48a3}","{b72bd3bf}","{66fe0140}"],"unique":false,"org":{"desc":"\u5728\u73b0\u5728\u548c\u7b2c@MaxNumChests@\u9636\u6bb5\u4e4b\u95f4\u7684\u6bcf\u4e2a\u9636\u6bb5\u83b7\u5f97\u4e00\u4e2a\u4e0a\u9501\u7684\u5b9d\u7bb1\u3002\u5f53\u4f60\u5728\u5546\u5e97\u5237\u65b0\u4e0a\u82b1\u8d39@GoldNeededPerChest@\u91d1\u5e01\u65f6\uff0c\u5373\u53ef\u89e3\u9501\u4e00\u4e2a\u5b9d\u7bb1\u3002\u8fd9\u4e9b\u5b9d\u7bb1\u4f1a\u5b58\u7559\u81f3\u88ab\u6253\u5f00\u4e3a\u6b62\u3002","effects":{"GoldNeededPerChest":null,"MaxNumChests":null}},"_key":"TFT_Augment_TreasureHunt","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/TreasureHunt_II.TFT_Set15.png","removeSpaceName":"\u5bfb\u5b9d"}');
