INSERT INTO "augments" VALUES('TFT8_Augment_SalvageBinPlus','17.1b','打捞桶+','立刻获得1件随机成装，并在4个玩家对战回合之后提供1个基础装备。出售弈子会将其携带的成装拆分成基础装备(冠冕系装备和纹章除外)。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Salvage2.tex','[]','{"NumRounds":4}','{"apiName":"TFT8_Augment_SalvageBinPlus","associatedTraits":[],"composition":[],"desc":"\u7acb\u523b\u83b7\u5f971\u4ef6\u968f\u673a\u6210\u88c5\uff0c\u5e76\u57284\u4e2a\u73a9\u5bb6\u5bf9\u6218\u56de\u5408\u4e4b\u540e\u63d0\u4f9b1\u4e2a\u57fa\u7840\u88c5\u5907\u3002\u51fa\u552e\u5f08\u5b50\u4f1a\u5c06\u5176\u643a\u5e26\u7684\u6210\u88c5\u62c6\u5206\u6210\u57fa\u7840\u88c5\u5907(\u51a0\u5195\u7cfb\u88c5\u5907\u548c\u7eb9\u7ae0\u9664\u5916)\u3002","effects":{"NumRounds":4},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Salvage2.tex","id":null,"incompatibleTraits":[],"name":"\u6253\u635e\u6876+","tags":["{ce1fd21c}","{b72bd3bf}","{92e7310e}","{d02ae323}","{7aaa3b47}"],"unique":false,"org":{"desc":"\u7acb\u523b\u83b7\u5f971\u4ef6\u968f\u673a\u6210\u88c5\uff0c\u5e76\u5728@NumRounds@\u4e2a\u73a9\u5bb6\u5bf9\u6218\u56de\u5408\u4e4b\u540e\u63d0\u4f9b1\u4e2a\u57fa\u7840\u88c5\u5907\u3002\u51fa\u552e\u5f08\u5b50\u4f1a\u5c06\u5176\u643a\u5e26\u7684\u6210\u88c5\u62c6\u5206\u6210\u57fa\u7840\u88c5\u5907(\u51a0\u5195\u7cfb\u88c5\u5907\u548c\u7eb9\u7ae0\u9664\u5916)\u3002","effects":{"NumRounds":4}},"_key":"TFT8_Augment_SalvageBinPlus","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Salvage2.png","removeSpaceName":"\u6253\u635e\u6876+"}');
