INSERT INTO "augments" VALUES('TFT_Augment_SpeedyDoubleKill','17.1b','一波带走俩','获得1个【鬼索的狂暴之刃】。当2名玩家淘汰后，获得40金币。<br><br><tftitemrules>2021【命运之轮】全球总决赛</tftitemrules>','ASSETS/Maps/TFT/Icons/Augments/Hexcore/SpeedyDoubleKill_II.tex','[]','{"GoldAmount":40}','{"apiName":"TFT_Augment_SpeedyDoubleKill","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f971\u4e2a\u3010\u9b3c\u7d22\u7684\u72c2\u66b4\u4e4b\u5203\u3011\u3002\u5f532\u540d\u73a9\u5bb6\u6dd8\u6c70\u540e\uff0c\u83b7\u5f9740\u91d1\u5e01\u3002<br><br><tftitemrules>2021\u3010\u547d\u8fd0\u4e4b\u8f6e\u3011\u5168\u7403\u603b\u51b3\u8d5b</tftitemrules>","effects":{"GoldAmount":40},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/SpeedyDoubleKill_II.tex","id":null,"incompatibleTraits":[],"name":"\u4e00\u6ce2\u5e26\u8d70\u4fe9","tags":["{ce1fd21c}","{b72bd3bf}","{d12ae4b6}","{d22ae649}","{77b330ea}","{4529fead}"],"unique":false,"org":{"desc":"\u83b7\u5f971\u4e2a\u3010\u9b3c\u7d22\u7684\u72c2\u66b4\u4e4b\u5203\u3011\u3002\u5f532\u540d\u73a9\u5bb6\u6dd8\u6c70\u540e\uff0c\u83b7\u5f97@GoldAmount@\u91d1\u5e01\u3002<br><br><tftitemrules>2021\u3010\u547d\u8fd0\u4e4b\u8f6e\u3011\u5168\u7403\u603b\u51b3\u8d5b</tftitemrules>","effects":{"GoldAmount":40}},"_key":"TFT_Augment_SpeedyDoubleKill","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/SpeedyDoubleKill_II.TFT_Set16_ChampionAugments.png","removeSpaceName":"\u4e00\u6ce2\u5e26\u8d70\u4fe9"}');
