INSERT INTO "augments" VALUES('TFT11_Augment_Slammin_Plus','17.1b','物尽其用+','立刻获得8金币和10经验值。每个玩家对战回合结束时，如果你的备战席没有任何装备(消耗品除外)，则获得2经验值。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Slammin_II.tex','[]','{"Gold":8,"XP":2,"XPNow":10,"components":null}','{"apiName":"TFT11_Augment_Slammin_Plus","associatedTraits":[],"composition":[],"desc":"\u7acb\u523b\u83b7\u5f978\u91d1\u5e01\u548c10\u7ecf\u9a8c\u503c\u3002\u6bcf\u4e2a\u73a9\u5bb6\u5bf9\u6218\u56de\u5408\u7ed3\u675f\u65f6\uff0c\u5982\u679c\u4f60\u7684\u5907\u6218\u5e2d\u6ca1\u6709\u4efb\u4f55\u88c5\u5907(\u6d88\u8017\u54c1\u9664\u5916)\uff0c\u5219\u83b7\u5f972\u7ecf\u9a8c\u503c\u3002","effects":{"Gold":8,"XP":2,"XPNow":10,"components":null},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Slammin_II.tex","id":null,"incompatibleTraits":[],"name":"\u7269\u5c3d\u5176\u7528+","tags":["{ce1fd21c}","{b72bd3bf}","{d22ae649}","{d02ae323}","{7aaa3b47}","{77b330ea}","{24d36c27}"],"unique":false,"org":{"desc":"\u7acb\u523b\u83b7\u5f97@Gold@\u91d1\u5e01\u548c@XPNow@\u7ecf\u9a8c\u503c\u3002\u6bcf\u4e2a\u73a9\u5bb6\u5bf9\u6218\u56de\u5408\u7ed3\u675f\u65f6\uff0c\u5982\u679c\u4f60\u7684\u5907\u6218\u5e2d\u6ca1\u6709\u4efb\u4f55\u88c5\u5907(\u6d88\u8017\u54c1\u9664\u5916)\uff0c\u5219\u83b7\u5f97@XP@\u7ecf\u9a8c\u503c\u3002","effects":{"Gold":8,"XP":2,"XPNow":10,"components":null}},"_key":"TFT11_Augment_Slammin_Plus","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Slammin_II.png","removeSpaceName":"\u7269\u5c3d\u5176\u7528+"}');
