INSERT INTO "augments" VALUES('TFT_Augment_TwinGuardians','17.1b','双子守护神','如果你的第一排有且只有2个弈子，为他们提供100额外生命值、35护甲和35魔抗。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/TwinGuardians_I.TFT_Set16.tex','[]','{"BonusAR":35,"BonusHealth":100,"BonusMR":35,"NumUnits":2,"{2b04af7e}":1}','{"apiName":"TFT_Augment_TwinGuardians","associatedTraits":[],"composition":[],"desc":"\u5982\u679c\u4f60\u7684\u7b2c\u4e00\u6392\u6709\u4e14\u53ea\u67092\u4e2a\u5f08\u5b50\uff0c\u4e3a\u4ed6\u4eec\u63d0\u4f9b100\u989d\u5916\u751f\u547d\u503c\u300135\u62a4\u7532\u548c35\u9b54\u6297\u3002","effects":{"BonusAR":35,"BonusHealth":100,"BonusMR":35,"NumUnits":2,"{2b04af7e}":1},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/TwinGuardians_I.TFT_Set16.tex","id":null,"incompatibleTraits":[],"name":"\u53cc\u5b50\u5b88\u62a4\u795e","tags":["{d11fd6d5}","{b72bd3bf}","{d02ae323}","{807eed8a}"],"unique":false,"org":{"desc":"\u5982\u679c\u4f60\u7684\u7b2c\u4e00\u6392\u6709\u4e14\u53ea\u6709@NumUnits@\u4e2a\u5f08\u5b50\uff0c\u4e3a\u4ed6\u4eec\u63d0\u4f9b@BonusHealth@\u989d\u5916\u751f\u547d\u503c\u3001@BonusAR@\u62a4\u7532\u548c@BonusMR@\u9b54\u6297\u3002","effects":{"BonusAR":35,"BonusHealth":100,"BonusMR":35,"NumUnits":2,"{2b04af7e}":1}},"_key":"TFT_Augment_TwinGuardians","tier":"silver","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/TwinGuardians_I.TFT_Set16.png","balance":-1,"diff":{"effects":["BonusAR","BonusMR"]},"removeSpaceName":"\u53cc\u5b50\u5b88\u62a4\u795e"}');
