INSERT INTO "augments" VALUES('TFT_Augment_GoldenGamblePlus','17.1b','黄金赌约+','获得4金币，并抛一枚硬币。如果硬币正面朝上，获得1个光明版幸运装备宝箱。如果硬币反面朝上，获得2个成装锻造器。<br><br>@TFTUnitProperty.item:TFT_Augment_GoldenGamble_Tooltip@','ASSETS/Maps/TFT/Icons/Augments/Hexcore/GoldenGamble_III.TFT_Set17.tex','[]','{"CompletedAnvils":2,"Gold":4}','{"apiName":"TFT_Augment_GoldenGamblePlus","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f974\u91d1\u5e01\uff0c\u5e76\u629b\u4e00\u679a\u786c\u5e01\u3002\u5982\u679c\u786c\u5e01\u6b63\u9762\u671d\u4e0a\uff0c\u83b7\u5f971\u4e2a\u5149\u660e\u7248\u5e78\u8fd0\u88c5\u5907\u5b9d\u7bb1\u3002\u5982\u679c\u786c\u5e01\u53cd\u9762\u671d\u4e0a\uff0c\u83b7\u5f972\u4e2a\u6210\u88c5\u953b\u9020\u5668\u3002<br><br>@TFTUnitProperty.item:TFT_Augment_GoldenGamble_Tooltip@","effects":{"CompletedAnvils":2,"Gold":4},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/GoldenGamble_III.TFT_Set17.tex","id":null,"incompatibleTraits":[],"name":"\u9ec4\u91d1\u8d4c\u7ea6+","tags":["{cf1fd3af}","{b72bd3bf}","{8fba48a3}","{d02ae323}","{d22ae649}"],"unique":false,"org":{"desc":"\u83b7\u5f97@gold@\u91d1\u5e01\uff0c\u5e76\u629b\u4e00\u679a\u786c\u5e01\u3002\u5982\u679c\u786c\u5e01\u6b63\u9762\u671d\u4e0a\uff0c\u83b7\u5f971\u4e2a\u5149\u660e\u7248\u5e78\u8fd0\u88c5\u5907\u5b9d\u7bb1\u3002\u5982\u679c\u786c\u5e01\u53cd\u9762\u671d\u4e0a\uff0c\u83b7\u5f97@CompletedAnvils@\u4e2a\u6210\u88c5\u953b\u9020\u5668\u3002<br><br>@TFTUnitProperty.item:TFT_Augment_GoldenGamble_Tooltip@","effects":{"CompletedAnvils":2,"Gold":4}},"_key":"TFT_Augment_GoldenGamblePlus","tier":"prism","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/GoldenGamble_III.TFT_Set17.png","removeSpaceName":"\u9ec4\u91d1\u8d4c\u7ea6+"}');
INSERT INTO "augments" VALUES('TFT_Augment_AnExaltedAdventure','17.1b','崇高冒险','获得3名2费弈子。如果你将他们当中的两个升为3星，将获得一个充满战利品的法球。在接下来的2个阶段开始时会获得1个【次级英雄复制器】。<br><br>弈子：@TFTUnitProperty.item:TFT_Augment_ExaltedAdventure_Champs@，@TFTUnitProperty.item:TFT_Augment_ExaltedAdventure_Champs2@，@TFTUnitProperty.item:TFT_Augment_ExaltedAdventure_Champs3@','ASSETS/Maps/TFT/Icons/Augments/Hexcore/ExaltedAdventure_III.TFT_Set13.tex','[]','{"NumStages":2,"NumUnits":3}','{"apiName":"TFT_Augment_AnExaltedAdventure","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f973\u540d2\u8d39\u5f08\u5b50\u3002\u5982\u679c\u4f60\u5c06\u4ed6\u4eec\u5f53\u4e2d\u7684\u4e24\u4e2a\u5347\u4e3a3\u661f\uff0c\u5c06\u83b7\u5f97\u4e00\u4e2a\u5145\u6ee1\u6218\u5229\u54c1\u7684\u6cd5\u7403\u3002\u5728\u63a5\u4e0b\u6765\u76842\u4e2a\u9636\u6bb5\u5f00\u59cb\u65f6\u4f1a\u83b7\u5f971\u4e2a\u3010\u6b21\u7ea7\u82f1\u96c4\u590d\u5236\u5668\u3011\u3002<br><br>\u5f08\u5b50\uff1a@TFTUnitProperty.item:TFT_Augment_ExaltedAdventure_Champs@\uff0c@TFTUnitProperty.item:TFT_Augment_ExaltedAdventure_Champs2@\uff0c@TFTUnitProperty.item:TFT_Augment_ExaltedAdventure_Champs3@","effects":{"NumStages":2,"NumUnits":3},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/ExaltedAdventure_III.TFT_Set13.tex","id":null,"incompatibleTraits":[],"name":"\u5d07\u9ad8\u5192\u9669","tags":["{cf1fd3af}","{b72bd3bf}","{d22ae649}","{d12ae4b6}","{84a6d904}","{7aaa3b47}","{382a7131}","{92e7310e}"],"unique":false,"org":{"desc":"\u83b7\u5f973\u540d2\u8d39\u5f08\u5b50\u3002\u5982\u679c\u4f60\u5c06\u4ed6\u4eec\u5f53\u4e2d\u7684\u4e24\u4e2a\u5347\u4e3a3\u661f\uff0c\u5c06\u83b7\u5f97\u4e00\u4e2a\u5145\u6ee1\u6218\u5229\u54c1\u7684\u6cd5\u7403\u3002\u5728\u63a5\u4e0b\u6765\u7684@NumStages@\u4e2a\u9636\u6bb5\u5f00\u59cb\u65f6\u4f1a\u83b7\u5f971\u4e2a\u3010\u6b21\u7ea7\u82f1\u96c4\u590d\u5236\u5668\u3011\u3002<br><br>\u5f08\u5b50\uff1a@TFTUnitProperty.item:TFT_Augment_ExaltedAdventure_Champs@\uff0c@TFTUnitProperty.item:TFT_Augment_ExaltedAdventure_Champs