INSERT INTO "augments" VALUES('TFT_Augment_BirthdayReunion','17.1b','生日聚会','获得1个随机2星2费弈子。在你到达7级时，获得一个【窃贼手套】。在你到达9级时，获得1个随机2星5费弈子。<br><br><tftitemrules>2024【画中灵】全球总决赛</tftitemrules>','ASSETS/Maps/TFT/Icons/Augments/Hexcore/BirthdayReunion_II.tex','[]','{"FirstLevelBreakpoint":7,"SecondLevelBreakpoint":9}','{"apiName":"TFT_Augment_BirthdayReunion","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f971\u4e2a\u968f\u673a2\u661f2\u8d39\u5f08\u5b50\u3002\u5728\u4f60\u5230\u8fbe7\u7ea7\u65f6\uff0c\u83b7\u5f97\u4e00\u4e2a\u3010\u7a83\u8d3c\u624b\u5957\u3011\u3002\u5728\u4f60\u5230\u8fbe9\u7ea7\u65f6\uff0c\u83b7\u5f971\u4e2a\u968f\u673a2\u661f5\u8d39\u5f08\u5b50\u3002<br><br><tftitemrules>2024\u3010\u753b\u4e2d\u7075\u3011\u5168\u7403\u603b\u51b3\u8d5b</tftitemrules>","effects":{"FirstLevelBreakpoint":7,"SecondLevelBreakpoint":9},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/BirthdayReunion_II.tex","id":null,"incompatibleTraits":[],"name":"\u751f\u65e5\u805a\u4f1a","tags":["{ce1fd21c}","{b72bd3bf}","{d12ae4b6}","{d22ae649}","{4529fead}"],"unique":false,"org":{"desc":"\u83b7\u5f971\u4e2a\u968f\u673a2\u661f2\u8d39\u5f08\u5b50\u3002\u5728\u4f60\u5230\u8fbe@FirstLevelBreakpoint@\u7ea7\u65f6\uff0c\u83b7\u5f97\u4e00\u4e2a\u3010\u7a83\u8d3c\u624b\u5957\u3011\u3002\u5728\u4f60\u5230\u8fbe@SecondLevelBreakpoint@\u7ea7\u65f6\uff0c\u83b7\u5f971\u4e2a\u968f\u673a2\u661f5\u8d39\u5f08\u5b50\u3002<br><br><tftitemrules>2024\u3010\u753b\u4e2d\u7075\u3011\u5168\u7403\u603b\u51b3\u8d5b</tftitemrules>","effects":{"FirstLevelBreakpoint":7,"SecondLevelBreakpoint":9}},"_key":"TFT_Augment_BirthdayReunion","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/BirthdayReunion_II.TFT_Set16_ChampionAugments.png","removeSpaceName":"\u751f\u65e5\u805a\u4f1a"}');
