INSERT INTO "augments" VALUES('TFT_Augment_LuxurySubscription','17.1b','奢侈品订购','获得1个包裹，包含1个5费弈子、1个2星1费弈子和5金币。<br><br>在接下来的2个阶段开始时，再次获得该包裹。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/LuxurySubscription_III.TFT_Set16.tex','[]','{"FutureChampionCount":2,"Gold":5}','{"apiName":"TFT_Augment_LuxurySubscription","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f971\u4e2a\u5305\u88f9\uff0c\u5305\u542b1\u4e2a5\u8d39\u5f08\u5b50\u30011\u4e2a2\u661f1\u8d39\u5f08\u5b50\u548c5\u91d1\u5e01\u3002<br><br>\u5728\u63a5\u4e0b\u6765\u76842\u4e2a\u9636\u6bb5\u5f00\u59cb\u65f6\uff0c\u518d\u6b21\u83b7\u5f97\u8be5\u5305\u88f9\u3002","effects":{"FutureChampionCount":2,"Gold":5},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/LuxurySubscription_III.TFT_Set16.tex","id":null,"incompatibleTraits":[],"name":"\u5962\u4f88\u54c1\u8ba2\u8d2d","tags":["{cf1fd3af}","{b72bd3bf}","{d02ae323}","{d22ae649}","{7aaa3b47}"],"unique":false,"org":{"desc":"\u83b7\u5f971\u4e2a\u5305\u88f9\uff0c\u5305\u542b1\u4e2a5\u8d39\u5f08\u5b50\u30011\u4e2a2\u661f1\u8d39\u5f08\u5b50\u548c@Gold@\u91d1\u5e01\u3002<br><br>\u5728\u63a5\u4e0b\u6765\u7684@FutureChampionCount@\u4e2a\u9636\u6bb5\u5f00\u59cb\u65f6\uff0c\u518d\u6b21\u83b7\u5f97\u8be5\u5305\u88f9\u3002","effects":{"FutureChampionCount":2,"Gold":5}},"_key":"TFT_Augment_LuxurySubscription","tier":"prism","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/LuxurySubscription_III.TFT_Set16.png","removeSpaceName":"\u5962\u4f88\u54c1\u8ba2\u8d2d"}');
