INSERT INTO "augments" VALUES('TFT_Augment_TwoTanky','17.1b','坦度成双','如果你恰好登场了相同英雄的2个弈子，那么他们都会获得500生命值。在其中一个弈子阵亡时，另一个获得持续12秒的相当于40%最大生命值的护盾值。当你将弈子升到3星时，获得该英雄的1个2星弈子。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Two-Tanky-II.tex','[]','{"BonusHealth":500,"HealDuration":12,"OnDeathPercHeal":0.4000000059604645}','{"apiName":"TFT_Augment_TwoTanky","associatedTraits":[],"composition":[],"desc":"\u5982\u679c\u4f60\u6070\u597d\u767b\u573a\u4e86\u76f8\u540c\u82f1\u96c4\u76842\u4e2a\u5f08\u5b50\uff0c\u90a3\u4e48\u4ed6\u4eec\u90fd\u4f1a\u83b7\u5f97500\u751f\u547d\u503c\u3002\u5728\u5176\u4e2d\u4e00\u4e2a\u5f08\u5b50\u9635\u4ea1\u65f6\uff0c\u53e6\u4e00\u4e2a\u83b7\u5f97\u6301\u7eed12\u79d2\u7684\u76f8\u5f53\u4e8e40%\u6700\u5927\u751f\u547d\u503c\u7684\u62a4\u76fe\u503c\u3002\u5f53\u4f60\u5c06\u5f08\u5b50\u5347\u52303\u661f\u65f6\uff0c\u83b7\u5f97\u8be5\u82f1\u96c4\u76841\u4e2a2\u661f\u5f08\u5b50\u3002","effects":{"BonusHealth":500,"HealDuration":12,"OnDeathPercHeal":0.4000000059604645},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Two-Tanky-II.tex","id":null,"incompatibleTraits":[],"name":"\u5766\u5ea6\u6210\u53cc","tags":["{ce1fd21c}","{b72bd3bf}","{92e7310e}","{d22ae649}","{66fe0140}"],"unique":false,"org":{"desc":"\u5982\u679c\u4f60\u6070\u597d\u767b\u573a\u4e86\u76f8\u540c\u82f1\u96c4\u76842\u4e2a\u5f08\u5b50\uff0c\u90a3\u4e48\u4ed6\u4eec\u90fd\u4f1a\u83b7\u5f97@BonusHealth@\u751f\u547d\u503c\u3002\u5728\u5176\u4e2d\u4e00\u4e2a\u5f08\u5b50\u9635\u4ea1\u65f6\uff0c\u53e6\u4e00\u4e2a\u83b7\u5f97\u6301\u7eed@HealDuration@\u79d2\u7684\u76f8\u5f53\u4e8e@OnDeathPercHeal*100@%\u6700\u5927\u751f\u547d\u503c\u7684\u62a4\u76fe\u503c\u3002\u5f53\u4f60\u5c06\u5f08\u5b50\u5347\u52303\u661f\u65f6\uff0c\u83b7\u5f97\u8be5\u82f1\u96c4\u76841\u4e2a2\u661f\u5f08\u5b50\u3002","effects":{"BonusHealth":500,"HealDuration":12,"OnDeathPercHeal":0.4000000059604645}},"_key":"TFT_Augment_TwoTanky","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Two-Tanky-II.png","balan