INSERT INTO "augments" VALUES('TFT7_Augment_BirthdayPresents','17.1b','生日礼物','在你每次升级时提供1个2星弈子和1金币。这个弈子的费用位阶是你的等级减4(最大值：5费)。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Golden-Gifts-III.tex','[]','{"Gold":1}','{"apiName":"TFT7_Augment_BirthdayPresents","associatedTraits":[],"composition":[],"desc":"\u5728\u4f60\u6bcf\u6b21\u5347\u7ea7\u65f6\u63d0\u4f9b1\u4e2a2\u661f\u5f08\u5b50\u548c1\u91d1\u5e01\u3002\u8fd9\u4e2a\u5f08\u5b50\u7684\u8d39\u7528\u4f4d\u9636\u662f\u4f60\u7684\u7b49\u7ea7\u51cf4(\u6700\u5927\u503c\uff1a5\u8d39)\u3002","effects":{"Gold":1},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Golden-Gifts-III.tex","id":null,"incompatibleTraits":[],"name":"\u751f\u65e5\u793c\u7269","tags":["{cf1fd3af}","{b72bd3bf}","{24d36c27}","{d12ae4b6}","{d22ae649}","{7aaa3b47}","{382a7131}"],"unique":false,"org":{"desc":"\u5728\u4f60\u6bcf\u6b21\u5347\u7ea7\u65f6\u63d0\u4f9b1\u4e2a2\u661f\u5f08\u5b50\u548c@Gold@\u91d1\u5e01\u3002\u8fd9\u4e2a\u5f08\u5b50\u7684\u8d39\u7528\u4f4d\u9636\u662f\u4f60\u7684\u7b49\u7ea7\u51cf4(\u6700\u5927\u503c\uff1a5\u8d39)\u3002","effects":{"Gold":1}},"_key":"TFT7_Augment_BirthdayPresents","tier":"prism","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Golden-Gifts-III.png","removeSpaceName":"\u751f\u65e5\u793c\u7269"}');
INSERT INTO "augments" VALUES('TFT_Augment_JustSlayer','17.1b','无差别攻击','获得1个【巨人杀手】。【巨人杀手】的伤害增幅现在对所有敌人生效，而不是仅对【坦克】。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/IndiscriminateSlayer_II.TFT_Set16.tex','[]','{}','{"apiName":"TFT_Augment_JustSlayer","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f971\u4e2a\u3010\u5de8\u4eba\u6740\u624b\u3011\u3002\u3010\u5de8\u4eba\u6740\u624b\u3011\u7684\u4f24\u5bb3\u589e\u5e45\u73b0\u5728\u5bf9\u6240\u6709\u654c\u4eba\u751f\u6548\uff0c\u800c\u4e0d\u662f\u4ec5\u5bf9\u3010\u5766\u514b\u3011\u3002","effects":{},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/IndiscriminateSlayer_II.TFT_Set16.tex","id":null,"incompatibleTraits":[],"name":"\u65e0\u5dee\u522b\u653b\u51fb","tags":["{ce1fd21c}","{8fba48a3}","{b72bd3bf}","{d02ae323}"],"unique":false,"org":{"desc":"\u83b7\u5f971\u4e2a\u3010\u5de8\u4eba\u6740\u624b\u3011\u3002\u3010\u5de8\u4eba\u6740\u624b\u3011\u7684\u4f24\u5bb3\u589e\u5e45\u73b0\u5728\u5bf9\u6240\u6709\u654c\u4eba\u751f\u6548\uff0c\u800c\u4e0d\u662f\u4ec5\u5bf9\u3010\u5766\u514b\u3011\u3002","effects":{}},"_key":"TFT_Augment_JustSlayer","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/IndiscriminateSlayer_II.TFT_Set16.png","removeSpaceName":"\u65e0\u5dee\u522b\u653b\u51fb"}');
INSERT INTO "augments" VALUES('TFT_Augment_ShimmerscaleEssence','17.1b','金鳞精粹','获得1个【大亨之铠】。在6回合内，获得1个【投机者之刃】。<br><br><rules>这些装备会在提供战斗力的同时给予金币。</rules>','ASSETS/Maps/TFT/Icons/Augments/Hexcore/ShimmerscaleEssence_III.TFT_Set12.tex','[]','{"CombatNum":6}','{"apiName":"TFT_Augment_ShimmerscaleEssence","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f971\u4e2a\u3010\u5927\u4ea8\u4e4b\u94e0\u3011\u3002\u57286\u56de\u5408\u5185\uff0c\u83b7\u5f971\u4e2a\u3010\u6295\u673a\u8005\u4e4b\u5203\u3011\u3002<br><br><rules>\u8fd9\u4e9b\u88c5\u5907\u4f1a\u5728\u63d0\u4f9b\u6218\u6597\u529b\u7684\u540c\u65f6\u7ed9\u4e88\u91d1\u5e01\u3002</rules>","effects":{"CombatNum":6},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/ShimmerscaleEssence_III.TFT_Set12.tex","id":null,"incompatibleTraits":[],"name":"\u91d1\u9cde\u7cbe\u7cb9","tags":["{cf1fd3af}","{b72bd3bf}","{d12ae4b6}","{d22ae649}","{7aaa3b47}","{8fba48a3}","{24d36c27}"],"unique":false,"org":{"desc":"\u83b7\u5f971\u4e2a\u3010\u5927\u4ea8\u4e4b\u94e0\u3011\u3002\u5728@combatnum@\u56de\u5408\u5185\uff0c\u83b7\u5f971\u4e2a\u3010\u6295\u673a\u8005\u4e4b\u5203\u3011\u3002<br><br><rules>\u8fd9\u4e9b\u88c5\u5907\u4f1a\u5728\u63d0\u4f9b\u6218\u6597\u529b\u7684\u540c\u65f6\u7ed9\u4e88\u91d1\u5e01\u3002</rules>","effects":{"CombatNum":6}},"_key":"TFT_Augment_ShimmerscaleEssence","tier":"prism","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/ShimmerscaleEssence_III.TFT_Set12.png","removeSpaceName":"\u91d1\u9cde\u7cbe\u7cb9"}');
