INSERT INTO "augments" VALUES('TFT_Augment_ItemGargoyleStoneplate','17.1b','单身板甲','获得1个【石像鬼石板甲】。战斗开始时：携带了【石像鬼石板甲】并且独自站一排的那些己方弈子获得17%最大生命值。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/SoloPlate_II.TFT_Set16.tex','[]','{"HealthIncrease":0.17000000178813934}','{"apiName":"TFT_Augment_ItemGargoyleStoneplate","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f971\u4e2a\u3010\u77f3\u50cf\u9b3c\u77f3\u677f\u7532\u3011\u3002\u6218\u6597\u5f00\u59cb\u65f6\uff1a\u643a\u5e26\u4e86\u3010\u77f3\u50cf\u9b3c\u77f3\u677f\u7532\u3011\u5e76\u4e14\u72ec\u81ea\u7ad9\u4e00\u6392\u7684\u90a3\u4e9b\u5df1\u65b9\u5f08\u5b50\u83b7\u5f9717%\u6700\u5927\u751f\u547d\u503c\u3002","effects":{"HealthIncrease":0.17000000178813934},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/SoloPlate_II.TFT_Set16.tex","id":null,"incompatibleTraits":[],"name":"\u5355\u8eab\u677f\u7532","tags":["{ce1fd21c}","{b72bd3bf}","{d22ae649}","{8fba48a3}"],"unique":false,"org":{"desc":"\u83b7\u5f971\u4e2a\u3010\u77f3\u50cf\u9b3c\u77f3\u677f\u7532\u3011\u3002\u6218\u6597\u5f00\u59cb\u65f6\uff1a\u643a\u5e26\u4e86\u3010\u77f3\u50cf\u9b3c\u77f3\u677f\u7532\u3011\u5e76\u4e14\u72ec\u81ea\u7ad9\u4e00\u6392\u7684\u90a3\u4e9b\u5df1\u65b9\u5f08\u5b50\u83b7\u5f97@HealthIncrease*100@%\u6700\u5927\u751f\u547d\u503c\u3002","effects":{"HealthIncrease":0.17000000178813934}},"_key":"TFT_Augment_ItemGargoyleStoneplate","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/SoloPlate_II.TFT_Set16.png","balance":-1,"diff":{"effects":["HealthIncrease%"]},"removeSpaceName":"\u5355\u8eab\u677f\u7532"}');
