INSERT INTO "augments" VALUES('TFT_Augment_MoneyHungry','17.1b','贪财','立刻获得7金币，然后在每个阶段开始时获得7金币。拾取金币会令你的小小英雄变大。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/MoneyHungry1_II.TFT_Set17.tex','[]','{"InstantGold":7,"StageGold":7}','{"apiName":"TFT_Augment_MoneyHungry","associatedTraits":[],"composition":[],"desc":"\u7acb\u523b\u83b7\u5f977\u91d1\u5e01\uff0c\u7136\u540e\u5728\u6bcf\u4e2a\u9636\u6bb5\u5f00\u59cb\u65f6\u83b7\u5f977\u91d1\u5e01\u3002\u62fe\u53d6\u91d1\u5e01\u4f1a\u4ee4\u4f60\u7684\u5c0f\u5c0f\u82f1\u96c4\u53d8\u5927\u3002","effects":{"InstantGold":7,"StageGold":7},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/MoneyHungry1_II.TFT_Set17.tex","id":null,"incompatibleTraits":[],"name":"\u8d2a\u8d22","tags":["{ce1fd21c}","{b72bd3bf}","{24d36c27}","{d22ae649}","{d12ae4b6}","{7aaa3b47}","{ef273b4c}"],"unique":false,"org":{"desc":"\u7acb\u523b\u83b7\u5f97@InstantGold@\u91d1\u5e01\uff0c\u7136\u540e\u5728\u6bcf\u4e2a\u9636\u6bb5\u5f00\u59cb\u65f6\u83b7\u5f97@StageGold@\u91d1\u5e01\u3002\u62fe\u53d6\u91d1\u5e01\u4f1a\u4ee4\u4f60\u7684\u5c0f\u5c0f\u82f1\u96c4\u53d8\u5927\u3002","effects":{"InstantGold":7,"StageGold":7}},"_key":"TFT_Augment_MoneyHungry","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/MoneyHungry1_II.TFT_Set17.png","removeSpaceName":"\u8d2a\u8d22"}');
INSERT INTO "augments" VALUES('TFT_Augment_Waverider','17.1b','升星之运','每当你将1个在上一场战斗中登场的弈子升星时，获得1次免费商店刷新。获得6金币。','ASSETS/Maps/TFT/Icons/Augments/Hexcore/OnARoll_I.TFT_Set16.tex','[]','{"Gold":6,"Numrolls":1}','{"apiName":"TFT_Augment_Waverider","associatedTraits":[],"composition":[],"desc":"\u6bcf\u5f53\u4f60\u5c061\u4e2a\u5728\u4e0a\u4e00\u573a\u6218\u6597\u4e2d\u767b\u573a\u7684\u5f08\u5b50\u5347\u661f\u65f6\uff0c\u83b7\u5f971\u6b21\u514d\u8d39\u5546\u5e97\u5237\u65b0\u3002\u83b7\u5f976\u91d1\u5e01\u3002","effects":{"Gold":6,"Numrolls":1},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/OnARoll_I.TFT_Set16.tex","id":null,"incompatibleTraits":[],"name":"\u5347\u661f\u4e4b\u8fd0","tags":["{d11fd6d5}","{b72bd3bf}","{24d36c27}","{d22ae649}","{d02ae323}"],"unique":false,"org":{"desc":"\u6bcf\u5f53\u4f60\u5c061\u4e2a\u5728\u4e0a\u4e00\u573a\u6218\u6597\u4e2d\u767b\u573a\u7684\u5f08\u5b50\u5347\u661f\u65f6\uff0c\u83b7\u5f97@NumRolls@\u6b21\u514d\u8d39\u5546\u5e97\u5237\u65b0\u3002\u83b7\u5f97@Gold@\u91d1\u5e01\u3002","effects":{"Gold":6,"Numrolls":1}},"_key":"TFT_Augment_Waverider","tier":"silver","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/OnARoll_I.TFT_Set16.png","balance":0,"diff":{"effects":["Gold","Numrolls"]},"removeSpaceName":"\u5347\u661f\u4e4b\u8fd0"}');
