INSERT INTO "augments" VALUES('TFT_Augment_Pilfer','17.1b','挖角','每回合，获得你在上一场战斗中首先击杀的那个弈子的一个1星版本。当你通过这种方式获得的弈子总价值达到21金币时，获得1个【窃贼手套】。@TFTUnitProperty.item:TFT_Augment_Pilfer_Tooltip@<br><br>@TFTUnitProperty.item:TFT_Augment_Pilfer_RulesText@','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Pilfer_II.TFT_Set12.tex','[]','{"Gold":null,"goldrequired":21}','{"apiName":"TFT_Augment_Pilfer","associatedTraits":[],"composition":[],"desc":"\u6bcf\u56de\u5408\uff0c\u83b7\u5f97\u4f60\u5728\u4e0a\u4e00\u573a\u6218\u6597\u4e2d\u9996\u5148\u51fb\u6740\u7684\u90a3\u4e2a\u5f08\u5b50\u7684\u4e00\u4e2a1\u661f\u7248\u672c\u3002\u5f53\u4f60\u901a\u8fc7\u8fd9\u79cd\u65b9\u5f0f\u83b7\u5f97\u7684\u5f08\u5b50\u603b\u4ef7\u503c\u8fbe\u523021\u91d1\u5e01\u65f6\uff0c\u83b7\u5f971\u4e2a\u3010\u7a83\u8d3c\u624b\u5957\u3011\u3002@TFTUnitProperty.item:TFT_Augment_Pilfer_Tooltip@<br><br>@TFTUnitProperty.item:TFT_Augment_Pilfer_RulesText@","effects":{"Gold":null,"goldrequired":21},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Pilfer_II.TFT_Set12.tex","id":null,"incompatibleTraits":[],"name":"\u6316\u89d2","tags":["{ce1fd21c}","{b72bd3bf}","{d02ae323}","{7aaa3b47}","{24d36c27}","{d22ae649}"],"unique":false,"org":{"desc":"\u6bcf\u56de\u5408\uff0c\u83b7\u5f97\u4f60\u5728\u4e0a\u4e00\u573a\u6218\u6597\u4e2d\u9996\u5148\u51fb\u6740\u7684\u90a3\u4e2a\u5f08\u5b50\u7684\u4e00\u4e2a1\u661f\u7248\u672c\u3002\u5f53\u4f60\u901a\u8fc7\u8fd9\u79cd\u65b9\u5f0f\u83b7\u5f97\u7684\u5f08\u5b50\u603b\u4ef7\u503c\u8fbe\u5230@GoldRequired@\u91d1\u5e01\u65f6\uff0c\u83b7\u5f971\u4e2a\u3010\u7a83\u8d3c\u624b\u5957\u3011\u3002@TFTUnitProperty.item:TFT_Augment_Pilfer_Tooltip@<br><br>@TFTUnitProperty.item:TFT_Augment_Pilfer_RulesText@","effects":{"Gold":null,"goldrequired":21}},"_key":"TFT_Augment_Pilfer","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Pilfer_II.TFT_Set12.png","removeSpaceName":"\u6316\u89d2"}');
