INSERT INTO "augments" VALUES('TFT_Augment_Warpath','17.1b','征战之路','获得一个2星2费弈子。造成80玩家伤害后，获得一个装有高费弈子和装备的宝箱。<br>（当前：@TFTUnitProperty.item:TFT_Augment_Warpath_DamageCount@）','ASSETS/Maps/TFT/Icons/Augments/Hexcore/Warpath_II.TFT_Set13.tex','[]','{"PlayerDamage":80,"{16253d09}":null,"{3dc22ab3}":3,"{68c537b7}":null,"{6cf88c79}":1,"{7c96bf44}":2}','{"apiName":"TFT_Augment_Warpath","associatedTraits":[],"composition":[],"desc":"\u83b7\u5f97\u4e00\u4e2a2\u661f2\u8d39\u5f08\u5b50\u3002\u9020\u621080\u73a9\u5bb6\u4f24\u5bb3\u540e\uff0c\u83b7\u5f97\u4e00\u4e2a\u88c5\u6709\u9ad8\u8d39\u5f08\u5b50\u548c\u88c5\u5907\u7684\u5b9d\u7bb1\u3002<br>\uff08\u5f53\u524d\uff1a@TFTUnitProperty.item:TFT_Augment_Warpath_DamageCount@\uff09","effects":{"PlayerDamage":80,"{16253d09}":null,"{3dc22ab3}":3,"{68c537b7}":null,"{6cf88c79}":1,"{7c96bf44}":2},"from":null,"icon":"ASSETS/Maps/TFT/Icons/Augments/Hexcore/Warpath_II.TFT_Set13.tex","id":null,"incompatibleTraits":[],"name":"\u5f81\u6218\u4e4b\u8def","tags":["{ce1fd21c}","{d22ae649}","{d12ae4b6}","{b72bd3bf}","{7aaa3b47}","{77b330ea}","{4529fead}"],"unique":false,"org":{"desc":"\u83b7\u5f97\u4e00\u4e2a2\u661f2\u8d39\u5f08\u5b50\u3002\u9020\u6210@PlayerDamage@\u73a9\u5bb6\u4f24\u5bb3\u540e\uff0c\u83b7\u5f97\u4e00\u4e2a\u88c5\u6709\u9ad8\u8d39\u5f08\u5b50\u548c\u88c5\u5907\u7684\u5b9d\u7bb1\u3002<br>\uff08\u5f53\u524d\uff1a@TFTUnitProperty.item:TFT_Augment_Warpath_DamageCount@\uff09","effects":{"PlayerDamage":80,"{16253d09}":null,"{3dc22ab3}":3,"{68c537b7}":null,"{6cf88c79}":1,"{7c96bf44}":2}},"_key":"TFT_Augment_Warpath","tier":"gold","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-augment/Warpath_II.TFT_Set13.png","removeSpaceName":"\u5f81\u6218\u4e4b\u8def"}');
