INSERT INTO "traits" VALUES('TFT17_ShieldTank','17.1b','重装战士','class','ASSETS/UX/TraitIcons/Trait_Icon_12_Vanguard.TFT_Set12.tex','【重装战士】在拥有护盾时获得5%伤害减免。<br><br>对战开始时以及50%&nbsp;生命值时：获得一个最大生命值护盾，持续10秒。<br>','[{"maxUnits":3,"minUnits":2,"style":1,"variables":{"DamageReductionPct":0.05,"EnhancedDurability":0.08,"HealthThreshold":0.5,"ShieldDuration":10,"ShieldPercentAmount":0.16}},{"maxUnits":5,"minUnits":4,"style":3,"variables":{"DamageReductionPct":0.05,"EnhancedDurability":0.08,"HealthThreshold":0.5,"ShieldDuration":10,"ShieldPercentAmount":0.3}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"DamageReductionPct":0.05,"EnhancedDurability":0.08,"HealthThreshold":0.5,"ShieldDuration":10,"ShieldPercentAmount":0.4}}]','{"apiName":"TFT17_ShieldTank","desc":"\u3010\u91cd\u88c5\u6218\u58eb\u3011\u5728\u62e5\u6709\u62a4\u76fe\u65f6\u83b7\u5f975%\u4f24\u5bb3\u51cf\u514d\u3002<br><br>\u5bf9\u6218\u5f00\u59cb\u65f6\u4ee5\u53ca50%&nbsp;\u751f\u547d\u503c\u65f6\uff1a\u83b7\u5f97\u4e00\u4e2a\u6700\u5927\u751f\u547d\u503c\u62a4\u76fe\uff0c\u6301\u7eed10\u79d2\u3002<br>","effects":[{"maxUnits":3,"minUnits":2,"style":1,"variables":{"DamageReductionPct":0.05,"EnhancedDurability":0.08,"HealthThreshold":0.5,"ShieldDuration":10,"ShieldPercentAmount":0.16}},{"maxUnits":5,"minUnits":4,"style":3,"variables":{"DamageReductionPct":0.05,"EnhancedDurability":0.08,"HealthThreshold":0.5,"ShieldDuration":10,"ShieldPercentAmount":0.3}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"DamageReductionPct":0.05,"EnhancedDurability":0.08,"HealthThreshold":0.5,"ShieldDuration":10,"ShieldPercentAmount":0.4}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_12_Vanguard.TFT_Set12.tex","name":"\u91cd\u88c5\u6218\u58eb","org":{"desc":"\u3010\u91cd\u88c5\u6218\u58eb\u3011\u5728\u62e5\u6709\u62a4\u76fe\u65f6\u83b7\u5f97@DamageReductionPct*100@%\u4f24\u5bb3\u51cf\u514d\u3002<br><br>\u5bf9\u6218\u5f00\u59cb\u65f6\u4ee5\u53ca@HealthThreshold*100@%&nbsp;\u751f\u547d\u503c\u65f6\uff1a\u83b7\u5f97\u4e00\u4e2a\u