INSERT INTO "traits" VALUES('TFT17_MissFortuneUniqueTrait','17.1b','武装战姬','class','ASSETS/UX/TraitIcons/Trait_Icon_17_GunGoddess.TFT_Set17.tex','当你登场【厄运小姐】时，需要在【神谕模式】、【挑战者模式】、以及【魔术师模式】中选择一种。【厄运小姐】的每个模式都会为其提供1个独特的技能，同时她获得对应的羁绊。','[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"Allies":2,"DamageAmp":0.01,"FlatDamage":100,"Mana":2,"NumAttacks":3}}]','{"apiName":"TFT17_MissFortuneUniqueTrait","desc":"\u5f53\u4f60\u767b\u573a\u3010\u5384\u8fd0\u5c0f\u59d0\u3011\u65f6\uff0c\u9700\u8981\u5728\u3010\u795e\u8c15\u6a21\u5f0f\u3011\u3001\u3010\u6311\u6218\u8005\u6a21\u5f0f\u3011\u3001\u4ee5\u53ca\u3010\u9b54\u672f\u5e08\u6a21\u5f0f\u3011\u4e2d\u9009\u62e9\u4e00\u79cd\u3002\u3010\u5384\u8fd0\u5c0f\u59d0\u3011\u7684\u6bcf\u4e2a\u6a21\u5f0f\u90fd\u4f1a\u4e3a\u5176\u63d0\u4f9b1\u4e2a\u72ec\u7279\u7684\u6280\u80fd\uff0c\u540c\u65f6\u5979\u83b7\u5f97\u5bf9\u5e94\u7684\u7f81\u7eca\u3002","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"Allies":2,"DamageAmp":0.01,"FlatDamage":100,"Mana":2,"NumAttacks":3}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_GunGoddess.TFT_Set17.tex","name":"\u6b66\u88c5\u6218\u59ec","org":{"desc":"\u5f53\u4f60\u767b\u573a\u3010\u5384\u8fd0\u5c0f\u59d0\u3011\u65f6\uff0c\u9700\u8981\u5728\u3010\u795e\u8c15\u6a21\u5f0f\u3011\u3001\u3010\u6311\u6218\u8005\u6a21\u5f0f\u3011\u3001\u4ee5\u53ca\u3010\u9b54\u672f\u5e08\u6a21\u5f0f\u3011\u4e2d\u9009\u62e9\u4e00\u79cd\u3002\u3010\u5384\u8fd0\u5c0f\u59d0\u3011\u7684\u6bcf\u4e2a\u6a21\u5f0f\u90fd\u4f1a\u4e3a\u5176\u63d0\u4f9b1\u4e2a\u72ec\u7279\u7684\u6280\u80fd\uff0c\u540c\u65f6\u5979\u83b7\u5f97\u5bf9\u5e94\u7684\u7f81\u7eca\u3002","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"Allies":2,"DamageAmp":0.009999999776482582,"FlatDamage":100,"Mana":2,"NumAttacks":3}}]},"_key":"TFT17_MissFortuneUniqueTrait","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_GunGoddess.TFT_Set17.png","champions":[{"apiName":"TFT17_MissFortune","name":"\u5384\u8fd0\u5c0f\u59d0"}],"c