INSERT INTO "traits" VALUES('TFT17_AnimaSquad','17.1b','幻灵战队','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_AnimaTech.TFT_Set17.tex','在输掉1场玩家对战后，获得20【科技点】，并且会额外增加相当于你连败回合数5倍的【科技点】。此外，每个【幻灵战队】参与击杀时都会获得2【科技点】。<br><br>每当【幻灵战队】们获得100科技点，他们就会制造新的幻灵武器原型。你可以选择立刻拿走这些装备，或者保留你的【科技点】直到下一次获取更加强力的武器。<br>','[{"maxUnits":5,"minUnits":3,"style":1,"variables":{"TechBreakpoint":100,"TechPerCombat":20,"TechPerCombat_DU":20,"TechPerDeath_PVE":1,"TechPerKill":2,"TechPerLoss":5,"TechPerLoss_DU":5,"TechPerRound_PVE":20,"undefined":0.85}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"TechBreakpoint":100,"TechPerCombat":20,"TechPerCombat_DU":20,"TechPerDeath_PVE":1,"TechPerKill":2,"TechPerLoss":5,"TechPerLoss_DU":5,"TechPerRound_PVE":20,"undefined":0.85}}]','{"apiName":"TFT17_AnimaSquad","desc":"\u5728\u8f93\u63891\u573a\u73a9\u5bb6\u5bf9\u6218\u540e\uff0c\u83b7\u5f9720\u3010\u79d1\u6280\u70b9\u3011\uff0c\u5e76\u4e14\u4f1a\u989d\u5916\u589e\u52a0\u76f8\u5f53\u4e8e\u4f60\u8fde\u8d25\u56de\u5408\u65705\u500d\u7684\u3010\u79d1\u6280\u70b9\u3011\u3002\u6b64\u5916\uff0c\u6bcf\u4e2a\u3010\u5e7b\u7075\u6218\u961f\u3011\u53c2\u4e0e\u51fb\u6740\u65f6\u90fd\u4f1a\u83b7\u5f972\u3010\u79d1\u6280\u70b9\u3011\u3002<br><br>\u6bcf\u5f53\u3010\u5e7b\u7075\u6218\u961f\u3011\u4eec\u83b7\u5f97100\u79d1\u6280\u70b9\uff0c\u4ed6\u4eec\u5c31\u4f1a\u5236\u9020\u65b0\u7684\u5e7b\u7075\u6b66\u5668\u539f\u578b\u3002\u4f60\u53ef\u4ee5\u9009\u62e9\u7acb\u523b\u62ff\u8d70\u8fd9\u4e9b\u88c5\u5907\uff0c\u6216\u8005\u4fdd\u7559\u4f60\u7684\u3010\u79d1\u6280\u70b9\u3011\u76f4\u5230\u4e0b\u4e00\u6b21\u83b7\u53d6\u66f4\u52a0\u5f3a\u529b\u7684\u6b66\u5668\u3002<br>","effects":[{"maxUnits":5,"minUnits":3,"style":1,"variables":{"TechBreakpoint":100,"TechPerCombat":20,"TechPerCombat_DU":20,"TechPerDeath_PVE":1,"TechPerKill":2,"TechPerLoss":5,"TechPerLoss_DU":5,"TechPerRound_PVE":20,"undefined":0.85}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"TechBreakpoint":100,"TechPerCombat":20,"TechPerCombat_DU":20,"TechPer