INSERT INTO "traits" VALUES('TFT17_Stargazer_Fountain','17.1b','观星者 (泉水)','origin','ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex','【观星者】每局游戏会观测到一个不同的星座。本局游戏：<TFTStargazer>泉水</TFTStargazer>。<br><br>强化格内的友军获得1法力回复。强化格内的【观星者】获得更多，并且他们的技能现在会治疗最低生命值的友军。<br>','[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"Fountain_HealPercent":0.18,"Fountain_ManaRegen":1,"Fountain_ManaRegen_Teamwide":1}},{"maxUnits":25000,"minUnits":5,"style":4,"variables":{"Fountain_HealPercent":0.25,"Fountain_ManaRegen":5,"Fountain_ManaRegen_Teamwide":1}}]','{"apiName":"TFT17_Stargazer_Fountain","desc":"\u3010\u89c2\u661f\u8005\u3011\u6bcf\u5c40\u6e38\u620f\u4f1a\u89c2\u6d4b\u5230\u4e00\u4e2a\u4e0d\u540c\u7684\u661f\u5ea7\u3002\u672c\u5c40\u6e38\u620f\uff1a<TFTStargazer>\u6cc9\u6c34</TFTStargazer>\u3002<br><br>\u5f3a\u5316\u683c\u5185\u7684\u53cb\u519b\u83b7\u5f971\u6cd5\u529b\u56de\u590d\u3002\u5f3a\u5316\u683c\u5185\u7684\u3010\u89c2\u661f\u8005\u3011\u83b7\u5f97\u66f4\u591a\uff0c\u5e76\u4e14\u4ed6\u4eec\u7684\u6280\u80fd\u73b0\u5728\u4f1a\u6cbb\u7597\u6700\u4f4e\u751f\u547d\u503c\u7684\u53cb\u519b\u3002<br>","effects":[{"maxUnits":4,"minUnits":3,"style":1,"variables":{"Fountain_HealPercent":0.18,"Fountain_ManaRegen":1,"Fountain_ManaRegen_Teamwide":1}},{"maxUnits":25000,"minUnits":5,"style":4,"variables":{"Fountain_HealPercent":0.25,"Fountain_ManaRegen":5,"Fountain_ManaRegen_Teamwide":1}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Stargazer.TFT_Set17.tex","name":"\u89c2\u661f\u8005 (\u6cc9\u6c34)","org":{"desc":"\u3010\u89c2\u661f\u8005\u3011\u6bcf\u5c40\u6e38\u620f\u4f1a\u89c2\u6d4b\u5230\u4e00\u4e2a\u4e0d\u540c\u7684\u661f\u5ea7\u3002\u672c\u5c40\u6e38\u620f\uff1a<TFTStargazer>\u6cc9\u6c34</TFTStargazer>\u3002<br><br>\u5f3a\u5316\u683c\u5185\u7684\u53cb\u519b\u83b7\u5f97@Fountain_ManaRegen_Teamwide@\u6cd5\u529b\u56de\u590d\u3002\u5f3a\u5316\u683c\u5185\u7684\u3010\u89c2\u661f\u8005\u3011\u83b7\u5f97\u66f4\u591a\uff0c\u5e76\u4e14\u4ed6\u4eec\u7684\u6280\u80fd\u73b0\u5728\u4f1a\u6