INSERT INTO "traits" VALUES('TFT17_FlexTrait','17.1b','旅人','class','ASSETS/UX/TraitIcons/Trait_Icon_17_Voyager.TFT_Set17.tex','战斗开始时：你的坦克们获得持续15秒的护盾。你的其他友军获得伤害增幅。<br>【旅人】获得两倍此加成。<br>','[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"BonusDA":0.09,"ShieldDuration":15,"ShieldHP":175,"undefined":2}},{"maxUnits":3,"minUnits":3,"style":3,"variables":{"BonusDA":0.15,"ShieldDuration":15,"ShieldHP":250,"undefined":2}},{"maxUnits":4,"minUnits":4,"style":3,"variables":{"BonusDA":0.18,"ShieldDuration":15,"ShieldHP":350,"undefined":2}},{"maxUnits":5,"minUnits":5,"style":3,"variables":{"BonusDA":0.22,"ShieldDuration":15,"ShieldHP":500,"undefined":2}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"BonusDA":0.27,"ShieldDuration":15,"ShieldHP":700,"undefined":2}}]','{"apiName":"TFT17_FlexTrait","desc":"\u6218\u6597\u5f00\u59cb\u65f6\uff1a\u4f60\u7684\u5766\u514b\u4eec\u83b7\u5f97\u6301\u7eed15\u79d2\u7684\u62a4\u76fe\u3002\u4f60\u7684\u5176\u4ed6\u53cb\u519b\u83b7\u5f97\u4f24\u5bb3\u589e\u5e45\u3002<br>\u3010\u65c5\u4eba\u3011\u83b7\u5f97\u4e24\u500d\u6b64\u52a0\u6210\u3002<br>","effects":[{"maxUnits":2,"minUnits":2,"style":1,"variables":{"BonusDA":0.09,"ShieldDuration":15,"ShieldHP":175,"undefined":2}},{"maxUnits":3,"minUnits":3,"style":3,"variables":{"BonusDA":0.15,"ShieldDuration":15,"ShieldHP":250,"undefined":2}},{"maxUnits":4,"minUnits":4,"style":3,"variables":{"BonusDA":0.18,"ShieldDuration":15,"ShieldHP":350,"undefined":2}},{"maxUnits":5,"minUnits":5,"style":3,"variables":{"BonusDA":0.22,"ShieldDuration":15,"ShieldHP":500,"undefined":2}},{"maxUnits":25000,"minUnits":6,"style":4,"variables":{"BonusDA":0.27,"ShieldDuration":15,"ShieldHP":700,"undefined":2}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_Voyager.TFT_Set17.tex","name":"\u65c5\u4eba","org":{"desc":"\u6218\u6597\u5f00\u59cb\u65f6\uff1a\u4f60\u7684\u5766\u514b\u4eec\u83b7\u5f97\u6301\u7eed@ShieldDuration@\u79d2\u7684\u62a4\u76fe\u3002\u4f60\u7684\u5176\u4ed6\u53cb\u519b\u83b7\u5f97\u4f24\u5bb3\u589e\u5e45\