INSERT INTO "traits" VALUES('TFT17_BlitzcrankUniqueTrait','17.1b','汪星机器人','class','ASSETS/UX/TraitIcons/Trait_Icon_17_PartyAnimal.TFT_Set17.tex','每场战斗仅一次，在生命值降至45%后，变得不可被选取并且每秒回复15%最大生命值。生命值回满或没有其他友军存活时，返回战斗。如果生命值已回满，【布里茨】进入Space Groove状态，并且【派对破坏王】的被动会以四倍速召唤雷电，持续至战斗结束。','[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"HealthThreshold":0.45,"PercentHealthHeal":0.15}}]','{"apiName":"TFT17_BlitzcrankUniqueTrait","desc":"\u6bcf\u573a\u6218\u6597\u4ec5\u4e00\u6b21\uff0c\u5728\u751f\u547d\u503c\u964d\u81f345%\u540e\uff0c\u53d8\u5f97\u4e0d\u53ef\u88ab\u9009\u53d6\u5e76\u4e14\u6bcf\u79d2\u56de\u590d15%\u6700\u5927\u751f\u547d\u503c\u3002\u751f\u547d\u503c\u56de\u6ee1\u6216\u6ca1\u6709\u5176\u4ed6\u53cb\u519b\u5b58\u6d3b\u65f6\uff0c\u8fd4\u56de\u6218\u6597\u3002\u5982\u679c\u751f\u547d\u503c\u5df2\u56de\u6ee1\uff0c\u3010\u5e03\u91cc\u8328\u3011\u8fdb\u5165Space Groove\u72b6\u6001\uff0c\u5e76\u4e14\u3010\u6d3e\u5bf9\u7834\u574f\u738b\u3011\u7684\u88ab\u52a8\u4f1a\u4ee5\u56db\u500d\u901f\u53ec\u5524\u96f7\u7535\uff0c\u6301\u7eed\u81f3\u6218\u6597\u7ed3\u675f\u3002","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"HealthThreshold":0.45,"PercentHealthHeal":0.15}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_PartyAnimal.TFT_Set17.tex","name":"\u6c6a\u661f\u673a\u5668\u4eba","org":{"desc":"\u6bcf\u573a\u6218\u6597\u4ec5\u4e00\u6b21\uff0c\u5728\u751f\u547d\u503c\u964d\u81f3@HealthThreshold*100@%\u540e\uff0c\u53d8\u5f97\u4e0d\u53ef\u88ab\u9009\u53d6\u5e76\u4e14\u6bcf\u79d2\u56de\u590d@PercentHealthHeal*100@%\u6700\u5927\u751f\u547d\u503c\u3002\u751f\u547d\u503c\u56de\u6ee1\u6216\u6ca1\u6709\u5176\u4ed6\u53cb\u519b\u5b58\u6d3b\u65f6\uff0c\u8fd4\u56de\u6218\u6597\u3002\u5982\u679c\u751f\u547d\u503c\u5df2\u56de\u6ee1\uff0c\u3010\u5e03\u91cc\u8328\u3011\u8fdb\u5165{{TFT17_SpaceGroove_TheGroove}}\u72b6\u6001\uff0c\u5e76\u4e14\u3010\u6d3e\u5bf9\u7834\u574f\u738b\u3011\u7684\u88ab\u52a8\u4f1a\u4ee5\u56db\u500d\u901f\u53ec\u5524\u96f7\u7535\uff0c\u6301\u7eed\u81f3\u6218\u6597\u7ed3\u675f\u3002","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"HealthThreshold":0.44999998807907104,"PercentHealthHeal":0.15000000596046448}}]},"_key":"TFT17_BlitzcrankUniqueTrait","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_PartyAnimal.TFT_Set17.png","champions":[{"apiName":"TFT17_Blitzcrank","name":"\u5e03\u91cc\u8328"}],"category":"class","removeSpaceName":"\u6c6a\u661f\u673a\u5668\u4eba"}');
