INSERT INTO "traits" VALUES('TFT17_FioraUniqueTrait','17.1b','斗神','class','ASSETS/UX/TraitIcons/Trait_Icon_17_DivineDuelist.TFT_Set17.tex','你的小小英雄在获胜时回复相当于15%造成小小英雄伤害的生命值。<br>','[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"DUHeal":1,"PVEHP":1,"PVENumWins":4,"PlayerOmnivamp":0.15}}]','{"apiName":"TFT17_FioraUniqueTrait","desc":"\u4f60\u7684\u5c0f\u5c0f\u82f1\u96c4\u5728\u83b7\u80dc\u65f6\u56de\u590d\u76f8\u5f53\u4e8e15%\u9020\u6210\u5c0f\u5c0f\u82f1\u96c4\u4f24\u5bb3\u7684\u751f\u547d\u503c\u3002<br>","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"DUHeal":1,"PVEHP":1,"PVENumWins":4,"PlayerOmnivamp":0.15}}],"icon":"ASSETS/UX/TraitIcons/Trait_Icon_17_DivineDuelist.TFT_Set17.tex","name":"\u6597\u795e","org":{"desc":"\u4f60\u7684\u5c0f\u5c0f\u82f1\u96c4\u5728\u83b7\u80dc\u65f6\u56de\u590d\u76f8\u5f53\u4e8e@PlayerOmnivamp*100@%\u9020\u6210\u5c0f\u5c0f\u82f1\u96c4\u4f24\u5bb3\u7684\u751f\u547d\u503c\u3002<br><br>\u3010\u83f2\u5965\u5a1c\u3011\u603b\u4f1a\u5728\u4e00\u5bf9\u4e00\u7684\u5bf9\u51b3\u4e2d\u80dc\u51fa\u3002","effects":[{"maxUnits":25000,"minUnits":1,"style":4,"variables":{"DUHeal":1,"PVEHP":1,"PVENumWins":4,"PlayerOmnivamp":0.15000000596046448}}]},"_key":"TFT17_FioraUniqueTrait","imageUrl":"https://c-tft-api.op.gg/img/set/17/tft-trait/Trait_Icon_17_DivineDuelist.TFT_Set17.png","champions":[{"apiName":"TFT17_Fiora","name":"\u83f2\u5965\u5a1c"}],"category":"class","diff":{"effects.variables":["DUHeal","PVEHP","PVENumWins"]},"removeSpaceName":"\u6597\u795e"}');
